insert into public.questoes (numero, parte, capitulo, pergunta, resposta, status)
values
  (211, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Donde deriva a semelhança de caráter que muitas vezes existe entre dois irmãos, mormente se gêmeos?', 'São Espíritos simpáticos que se aproximam por analogia de sentimentos e se sentem felizes por estar juntos.', 'rascunho'),
  (212, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Há dois Espíritos, ou, por outra, duas almas, nas crianças cujos corpos nascem ligados, tendo comuns alguns órgãos?', 'Sim, mas a semelhança entre elas é tal que faz vos pareçam, em muitos casos, uma só.', 'rascunho'),
  (213, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Pois que nos gêmeos os Espíritos encarnam por simpatia, donde provém a aversão que às vezes se nota entre eles?', 'Não é de regra que sejam simpáticos os Espíritos dos gêmeos. Acontece também que Espíritos maus entendam de lutar juntos no palco da vida.', 'rascunho'),
  (214, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Que se deve pensar dessas histórias de crianças que lutam no seio materno?', 'Lendas! Para significarem quão inveterado era o ódio que reciprocamente se votavam, figuram-no a se fazer sentir antes do nascimento delas. Em geral, não levais muito em conta as imagens poéticas.', 'rascunho'),
  (215, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Que é o que dá origem ao caráter distintivo que se nota em cada povo? 100 – Allan Kar dec', 'Também os Espíritos se grupam em famílias, formando-as pela analogia de seus pendores mais ou menos puros, conforme a elevação que tenham alcançado. Pois bem! um povo é uma grande família formada pela reunião de Espíritos simpáticos. Na tendência que apresentam os membros dessas famílias, para se unirem, é que está a origem da semelhança que, existindo entre os indivíduos, constitui o caráter distintivo de cada povo. Julgas que Espíritos bons e humanitários procurem, para nele encarnar, um povo rude e grosseiro? Não. Os Espíritos simpatizam com as coletividades, como simpatizam com os indivíduos. Naquelas em cujo seio se encontrem, eles se acham no meio que lhes é próprio.', 'rascunho'),
  (216, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Em suas novas existências conservará o Espírito traços do caráter moral de suas existências anteriores?', 'Isso pode dar-se. Mas, melhorando-se, ele muda. Pode também acontecer que sua posição social venha a ser outra. Se de senhor passa a escravo, inteiramente diversos serão os seus gostos e dificilmente o reconheceríeis. Sendo o Espírito sempre o mesmo nas diversas encarnações, podem existir certas analogias entre as suas manifestações, se bem que modificadas pelos hábitos da posição que ocupe, até que um aperfeiçoamento notável lhe haja mudado completamente o caráter, porquanto, de orgulhoso e mau, pode tornar-se humilde e bondoso, se se arrependeu.', 'rascunho'),
  (217, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'E do caráter físico de suas existências pretéritas conserva o Espírito traços nas suas existências posteriores?', 'O novo corpo que ele toma nenhuma relação tem com o que foi anteriormente destruído. Entretanto, o Espírito se reflete no corpo. Sem dúvida que este é unicamente matéria, porém, nada obstante, se modela pelas capacidades do Espírito, que lhe imprime certo cunho, sobretudo ao rosto, pelo que é verdadeiro dizer-se que os olhos são o espelho da alma, isto é, que o semblante do indivíduo lhe reflete de modo particular a alma. Assim é que uma pessoa excessivamente feia, quando nela habita um Espírito bom, criterioso, humanitário, tem qualquer coisa que agrada, ao passo que há rostos belíssimos que nenhuma impressão te causam, que até chegam a inspirar-te repulsão. Poderias supor que somente corpos bem moldados servem de envoltório aos mais perfeitos Espíritos, quando o certo é que todos os dias deparas com homens de bem, sob um exterior disforme. Sem que haja pronunciada parecença, a semelhança dos gostos e das inclinações pode, portanto, dar lugar ao que se chama ‘um ar de família’." Nenhuma relação essencial guardando o corpo que a alma toma numa encarnação com o de que se revestiu em encarnação anterior, visto que aquele lhe pode vir de procedência muito diversa da deste, fora absurdo pretender-se que, numa série de existências, haja uma semelhança que é inteiramente fortuita. Todavia, as qualidades do Espírito freqüentemente modificam os órgãos que lhe servem para as manifestações e lhe imprimem ao semblante físico e até ao conjunto de suas maneiras um cunho especial. É assim que, sob um envoltório corporal da mais humilde aparência, se pode deparar a expressão da grandeza e da dignidade, enquanto sob um envoltório de aspecto senhoril se percebe freqüentemente a da baixeza e da ignomínia. Não é pouco freqüente observar-se que certas pessoas, elevando-se da mais ínfima posição, tomam sem esforços os hábitos e as maneiras da alta sociedade. Parece que elas aí vêm a achar-se de novo no seu elemento. Outras, contrariamente, apesar do nascimento e da educação, se mostram sempre deslocadas em tal meio. De que modo se há de explicar esse fato, senão como reflexo daquilo que o Espírito foi antes?', 'rascunho'),
  (218, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Encarnado, conserva o Espírito algum vestígio das percepções que teve e dos conhecimentos que adquiriu nas existências anteriores?', 'Guarda vaga lembrança, que lhe dá o que se chama idéias inatas." a) — Não é, então, quimérica a teoria das idéias inatas? "Não; os conhecimentos adquiridos em cada existência não mais se perdem. Liberto da matéria, o Espírito sempre os tem presentes. Durante a encarnação, esquece-os em parte, momentaneamente; porém, a intuição que deles conserva lhe auxilia o progresso. Se não fosse assim, teria que recomeçar constantemente. Em cada nova existência, o ponto de partida, para o Espírito, é o em que, na existência precedente, ele ficou." b) — Grande conexão deve então haver entre duas existências consecutivas? "Nem sempre tão grande quanto talvez o suponhas, dado que bem diferentes são, muitas vezes, as posições do Espírito nas duas e que, no intervalo de uma a outra, pode ele ter progredido.', 'rascunho'),
  (219, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Qual a origem das faculdades extraordinárias dos indivíduos que, sem estudo prévio, parecem ter a intuição de certos conhecimentos, o das línguas, do cálculo, etc.?', 'Lembrança do passado; progresso anterior da alma, mas de que ela não tem consciência. Donde queres que venham tais conhecimentos? O corpo muda, o Espírito, porém, não muda, embora troque de roupagem.', 'rascunho'),
  (220, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Pode o Espírito, mudando de corpo, perder algumas faculdades intelectuais, deixar de ter, por exemplo, o gosto das artes?', 'Sim, desde que conspurcou a sua inteligência ou a utilizou mal. Depois, uma faculdade qualquer pode permanecer adormecida durante uma existência, por querer o Espírito exercitar outra, que nenhuma relação tem com aquela. Esta, então, fica em estado latente, para reaparecer mais tarde.', 'rascunho'),
  (221, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Dever-se-ão atribuir a uma lembrança retrospectiva o sentimento instintivo que o homem, mesmo quando selvagem, possui da existência de Deus e o pressentimento da vida futura?', 'É uma lembrança que ele conserva do que sabia como Espírito antes de encarnar. Mas, o orgulho amiudadamente abafa esse sentimento." 102 – Allan Kar dec a) — Serão devidas a essa mesma lembrança certas crenças relativas à Doutrina Espírita, que se observam em todos os povos? "Esta doutrina é tão antiga quanto o mundo; tal o motivo por que em toda parte a encontramos, o que constitui prova de que é verdadeira. Conservando a intuição do seu estado de Espírito, o Espírito encarnado tem, instintivamente, consciência do mundo invisível, mas os preconceitos bastas vezes falseiam essa idéia e a ignorância lhe mistura a superstição.', 'rascunho'),
  (222, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo V — Considerações sobre a pluralidade das existências', 'Não é novo, dizem alguns, o dogma da reencarnação; ressuscitaram-no da doutrina de Pitágoras. Nunca dissemos ser de invenção moderna a Doutrina Espírita. Constituindo uma lei da Natureza, o Espiritismo há de ter existido desde a origem dos tempos e sempre nos esforçamos por demonstrar que dele se descobrem sinais na antiguidade mais remota. Pitágoras, como se sabe, não foi o autor do sistema da metempsicose; ele o colheu dos filósofos indianos e dos egípcios, que o tinham desde tempos imemoriais. A idéia da transmigração das almas formava, pois, uma crença vulgar, aceita pelos homens mais eminentes. De que modo a adquiriram? Por uma revelação, ou por intuição? Ignoramo-lo. Seja, porém, como for, o que não padece dúvida é que uma idéia não atravessa séculos e séculos, nem consegue impor-se a inteligências de escol, se não contiver algo de sério. Assim, a ancianidade desta doutrina, em vez de ser uma objeção, seria prova a seu favor. Contudo, entre a metempsicose dos antigos e a moderna doutrina da reencarnação, há, como também se sabe, profunda diferença, assinalada pelo fato de os Espíritos rejeitarem, de maneira absoluta, a transmigração da alma do homem para os animais e reciprocamente. Portanto, ensinando o dogma da pluralidade das existências corporais, os Espíritos renovam uma doutrina que teve origem nas primeiras idades do mundo e que se conservou no íntimo de muitas pessoas, até aos nossos dias. Simplesmente, eles a apresentam de um ponto de vista mais racional, mais acorde com as leis progressivas da Natureza e mais de conformidade com a sabedoria do Criador, despindo-a de todos os acessórios da superstição. Circunstância digna de nota é que não só neste livro os Espíritos a ensinaram no decurso dos últimos tempos: já 104 – Allan Kar dec antes da sua publicação, numerosas comunicações da mesma natureza se obtiveram em vários países, multiplicando-se depois, consideravelmente. Talvez fosse aqui o caso de examinarmos por que os Espíritos não parecem todos de acordo sobre esta questão. Mais tarde, porém, voltaremos a este assunto. Examinemos de outro ponto de vista a matéria e, abstraindo de qualquer intervenção dos Espíritos, deixemo-los de lado, por enquanto. Suponhamos que esta teoria nada tenha que ver com eles; suponhamos mesmo que jamais se haja cogitado de Espíritos. Coloquemo-nos, momentaneamente, num terreno neutro, admitindo o mesmo grau de probabilidade para ambas as hipóteses, isto é, a da pluralidade e a da unicidade das existências corpóreas, e vejamos para que lado a razão e o nosso próprio interesse nos farão pender. Muitos repelem a idéia da reencarnação pelo só motivo de ela não lhes convir. Dizem que uma existência já lhes chega de sobra e que, portanto, não desejariam recomeçar outra semelhante. De alguns sabemos que saltam em fúria só com o pensarem que tenham de voltar à Terra. Perguntar-lhes-emos apenas se imaginam que Deus lhes pediu o parecer, ou consultou os gostos, para regular o Universo. Uma de duas: ou a reencarnação existe, ou não existe; se existe, nada importa que os contrarie; terão que a sofrer, sem que para isso lhes peça Deus permissão. Afiguram-se-nos os que assim falam um doente a dizer: Sofri hoje bastante, não quero sofrer mais amanhã. Qualquer que seja o seu mau humor, não terá por isso que sofrer menos no dia seguinte, nem nos que se sucederem, até que se ache curado. Conseguintemente, se os que de tal maneira se externam tiverem que viver de novo, corporalmente, tornarão a viver, reencarnarão. Nada lhes adiantará rebelarem-se, quais crianças que não querem ir para o colégio, ou condenados, para a prisão. Passarão pelo que têm de passar. São demasiado pueris semelhantes objeções, para merecerem mais seriamente examinadas. Diremos, todavia, aos que as formulam que se tranqüilizem, que a Doutrina Espírita, no tocante à reencarnação, não é tão terrível como a julgam; que, se a houvessem estudado a fundo, não se mostrariam tão aterrorizados; saberiam que deles dependem as condições da nova existência, que será feliz ou desgraçada, conforme ao que tiverem feito neste mundo; que desde agora poderão elevar-se tão alto que a recaída no lodaçal não lhes seja mais de temer. Supomos dirigir-nos a pessoas que acreditam num futuro depois da morte e não aos que criam para si a perspectiva do nada, ou pretendem que suas almas se vão afogar num todo universal, onde perdem a individualidade, como os pingos da chuva no oceano, o que vem a dar quase no mesmo. Ora, pois: se credes num futuro qualquer, certo não admitis que ele seja idêntico para todos, porquanto, de outro modo, qual a utilidade do bem? Por que haveria o homem de constranger-se? Por que deixaria de satisfazer a todas as suas paixões, a todos os seus desejos, embora à custa de outrem, uma vez que por isso não ficaria sendo melhor, nem pior? Credes, ao contrário, que esse futuro será mais ou menos ditoso ou inditoso, conforme ao que houverdes feito durante a vida e então desejais que seja tão afortunado quanto possível, visto que há de durar pela eternidade, não? Mas, porventura, teríeis a pretensão de ser dos homens mais perfeitos que hajam existido na Terra e, pois, com direito a alcançardes de um salto a suprema felicidade dos eleitos? Não. Admitis então que há homens de valor maior do que o vosso e com direito a um lugar melhor, sem daí resultar que vos conteis entre os réprobos. Pois bem! Colocai-vos mentalmente, por um instante, nessa situação intermédia, que será a vossa, como acabastes de reconhecer, e imaginar que alguém vos venha dizer: Sofreis; não sois tão felizes quanto poderíeis ser, ao passo que diante de vós estão seres que gozam de completa ventura. Quereis mudar na deles a vossa posição? — Certamente, respondereis; que devemos fazer? — Quase nada: recomeçar o trabalho mal executado e executá-lo melhor. — Hesitaríeis em aceitar, ainda que a poder de muitas existências de provações? Façamos outra comparação mais prosaica. Figuremos que a um homem que, sem ter chegado à miséria extrema, sofre, no entanto, privações, por escassez de recursos, viessem dizer: Aqui está uma riqueza imensa de que podes gozar; para isto só é necessário que trabalhes arduamente durante um minuto. Fosse ele o mais preguiçoso da Terra, que sem hesitar diria: Trabalhemos um minuto, dois minutos, uma hora, um dia, se for preciso. Que importa isso, desde que me leve a acabar os meus dias na fartura? Ora, que é a duração da vida corpórea, em confronto com a eternidade? Menos que um minuto, menos que um segundo. Temos visto algumas pessoas raciocinarem deste modo: Não é possível que Deus, soberanamente bom como é, imponha ao homem a obrigação de recomeçar uma série de misérias e tribulações. Acharão, porventura, essas pessoas que há mais bondade em condenar Deus o homem a sofrer perpetuamente, por motivo de alguns momentos de erro, do que em lhe facultar meios de reparar suas faltas?', 'Dois industriais contrataram dois operários, cada um dos quais podia aspirar a se tornar sócio do respectivo patrão. Aconteceu que esses dois operários certa vez empregaram muito mal o seu dia, merecendo ambos ser despedidos. Um dos industriais, não obstante as súplicas do seu, o mandou embora e o pobre operário, não tendo achado mais trabalho, acabou por morrer na miséria. O outro disse ao seu: Perdeste um dia; deves-me por isso uma compensação. Executaste mal o teu trabalho; ficaste a me dever uma reparação. Consinto que o recomeces. Trata de executá-lo bem, que te conservarei ao meu serviço e poderás continuar aspirando à posição superior que te prometi." Será preciso perguntemos qual dos industriais foi mais humano? Dar-se-á que Deus, que é a clemência mesma, seja mais inexorável do que um homem? Alguma coisa de pungente há na idéia de que a nossa sorte fique para sempre decidida, por efeito de alguns anos de provações, ainda quando de nós não tenha dependido o atingirmos a perfeição, ao passo que eminentemente consoladora é a idéia oposta, que nos permite a esperança. Assim, sem nos pronunciarmos pró ou contra a pluralidade das existências, sem preferirmos uma hipótese a outra, declaramos que, se aos homens fosse dado escolher, ninguém quereria o julgamento sem apelação. Disse um filósofo que, se Deus não existisse, fora mister inventá-lo, para felicidade do gênero humano. Outro tanto se poderia dizer da pluralidade das existências. Mas, conforme atrás ponderamos, Deus não nos pede permissão, nem consulta os nossos gostos. Ou isto é, ou não é. Vejamos de que lado estão as probabilidades e encaremos de outro ponto de vista o assunto, unicamente como estudo filosófico, sempre abstraindo do ensino dos Espíritos. Se não há reencarnação, só há, evidentemente, uma existência corporal. Se a nossa atual existência corpórea é única, a alma de cada homem foi criada por ocasião do seu nascimento, a menos que se admita a anterioridade da alma, caso 106 – Allan Kar dec em que caberia perguntar o que era ela antes do nascimento e se o estado em que se achava não constituía uma existência sob forma qualquer. Não há meio termo: ou a alma existia, ou não existia antes do corpo. Se existia, qual a sua situação? Tinha, ou não, consciência de si mesma? Se não tinha, é quase como se não existisse. Se tinha individualidade, era progressiva, ou estacionária? Num e noutro caso, a que grau chegara ao tomar o corpo? Admitindo, de acordo com a crença vulgar, que a alma nasce com o corpo, ou, o que vem a ser o mesmo, que, antes de encarnar, só dispõe de faculdades negativas, perguntamos: 1º Por que mostra a alma aptidões tão diversas e independentes das idéias que a educação lhe fez adquirir? 2º Donde vem a aptidão extranormal que muitas crianças em tenra idade revelam, para esta ou aquela arte, para esta ou aquela ciência, enquanto outras se conservam inferiores ou medíocres durante a vida toda? 3º Donde, em uns, as idéias inatas ou intuitivas, que noutros não existem? 4º Donde, em certas crianças, o instinto precoce que revelam para os vícios ou para as virtudes, os sentimentos inatos de dignidade ou de baixeza, contrastando com o meio em que elas nasceram? 5º Por que, abstraindo-se da educação, uns homens são mais adiantados do que outros? 6º Por que há selvagens e homens civilizados? Se tomardes de um menino hotentote recém-nascido e o educardes nos nossos melhores liceus, fareis dele algum dia um Laplace ou um Newton? Qual a filosofia ou a teosofia capaz de resolver estes problemas? É fora de dúvida que, ou as almas são iguais ao nascerem, ou são desiguais. Se são iguais, por que, entre elas, tão grande diversidade de aptidões? Dir-se-á que isso depende do organismo. Mas, então, achamo-nos em presença da mais monstruosa e imoral das doutrinas. O homem seria simples máquina, joguete da matéria; deixaria de ter a responsabilidade de seus atos, pois que poderia atribuir tudo às suas imperfeições físicas. Se as almas são desiguais, é que Deus as criou assim. Nesse caso, porém, por que a inata superioridade concedida a algumas? Corresponderá essa parcialidade à justiça de Deus e ao amor que Ele consagra igualmente a todas as suas criaturas? Admitamos, ao contrário, uma série de progressivas existências anteriores para cada alma e tudo se explica. Ao nascerem, trazem os homens a intuição do que aprenderam antes: São mais ou menos adiantados, conforme o número de existências que contem, conforme já estejam mais ou menos afastados do ponto de partida. Dá-se aí exatamente o que se observa numa reunião de indivíduos de todas as idades, onde cada um terá desenvolvimento proporcionado ao número de anos que tenha vivido. As existências sucessivas serão, para a vida da alma, o que os anos são para a do corpo. Reuni, em certo dia, um milheiro de indivíduos de um a oitenta anos; suponde que um véu encubra todos os dias precedentes ao em que os reunistes e que, em conseqüência, acreditais que todos nasceram na mesma ocasião. Perguntareis naturalmente como é que uns são grandes e outros pequenos, uns velhos e jovens outros, instruídos uns, outros ainda ignorantes. Se, porém, dissipando-se a nuvem que lhes oculta o passado, vierdes a saber que todos hão vivido mais ou menos tempo, tudo se vos tornará explicado. Deus, em sua justiça, não pode ter criado almas desigualmente perfeitas. Com a pluralidade das existências, a desigualdade que notamos nada mais apresenta em oposição à mais rigorosa eqüidade: é que apenas vemos o presente e não o passado. A este raciocínio serve de base algum sistema, alguma suposição gratuita? Não. Partimos de um fato patente, incontestável: a desigualdade das aptidões e do desenvolvimento intelectual e moral e verificamos que nenhuma das teorias correntes o explica, ao passo que uma outra teoria lhe dá explicação simples, natural e lógica. Será racional preferir-se as que não explicam àquela que explica? À vista da sexta interrogação acima, dirão naturalmente que o hotentote é de raça inferior. Perguntaremos, então, se o hotentote é ou não um homem. Se é, por que a ele e à sua raça privou Deus dos privilégios concedidos à raça caucásica? Se não é, por que tentar fazê-lo cristão? A Doutrina Espírita tem mais amplitude do que tudo isto. Segundo ela, não há muitas espécies de homens, há tão- somente homens cujos espíritos estão mais ou menos atrasados, porém todos suscetíveis de progredir. Não é este princípio mais conforme à justiça de Deus? Vimos de apreciar a alma com relação ao seu passado e ao seu presente. Se a considerarmos, tendo em vista o seu futuro, esbarraremos nas mesmas dificuldades. 1ª Se a nossa existência atual é que, só ela, decidirá da nossa sorte vindoura, quais, na vida futura, as posições respectivas do selvagem e do homem civilizado? Estarão no mesmo nível, ou se acharão distanciados um do outro, no tocante à soma de felicidade eterna que lhes caiba? 2ª O homem que trabalhou toda a sua vida por melhorar-se, virá a ocupar a mesma categoria de outro que se conservou em grau inferior de adiantamento, não por culpa sua, mas porque não teve tempo, nem possibilidade de se tornar melhor? 3ª O que praticou o mal, por não ter podido instruir-se, será culpado de um estado de coisas cuja existência em nada dependeu dele? 4ª Trabalha-se continuamente por esclarecer, moralizar, civilizar os homens. Mas, em contraposição a um que fica esclarecido, milhões de outros morrem todos os dias antes que a luz lhes tenha chegado. Qual a sorte destes últimos? Serão tratados como réprobos? No caso contrário, que fizeram para ocupar categoria idêntica à dos outros? 5ª Que sorte aguarda os que morrem na infância, quando ainda não puderam fazer nem o bem, nem o mal? Se vão para o meio dos eleitos, por que esse favor, sem que coisa alguma hajam feito para merecê-lo? Em virtude de que privilégio eles se vêem isentos das tribulações da vida? Haverá alguma doutrina capaz de resolver esses problemas? Admitam-se as existências consecutivas e tudo se explicará conformemente à justiça de Deus. O que se não pôde fazer numa existência faz-se em outra. Assim é que ninguém escapa à lei do progresso, que cada um será recompensado segundo o seu merecimento real e que ninguém fica excluído da felicidade suprema, a que todos podem aspirar, quaisquer que sejam os obstáculos com que topem no caminho. Essas questões facilmente se multiplicariam ao infinito, porquanto inúmeros são os problemas psicológicos e morais que só na pluralidade das existências encontram solução. Limitamo-nos a formular as de ordem mais geral. 108 – Allan Kar dec Como quer que seja, alegar-se-á talvez que a Igreja não admite a doutrina da reencarnação; que ela subverteria a religião. Não temos o intuito de tratar dessa questão neste momento. Basta-nos o havermos demonstrado que aquela doutrina é eminentemente moral e racional. Ora, o que é moral e racional não pode estar em oposição a uma religião que proclama ser Deus a bondade e a razão por excelência. Que teria sido da religião, se, contra a opinião universal e o testemunho da ciência, se houvesse obstinadamente recusado a render-se à evidência e expulsado de seu seio todos os que não acreditassem no movimento do Sol ou nos seis dias da criação? Que crédito houvera merecido e que autoridade teria tido, entre povos cultos, uma religião fundada em erros manifestos e que os impusesse como artigos de fé? Logo que a evidência se patenteou, a Igreja, criteriosamente, se colocou do lado da evidência. Uma vez provado que certas coisas existentes seriam impossíveis sem a reencarnação, que, a não ser por esse meio, não se consegue explicar alguns pontos do dogma, cumpre admiti-lo e reconhecer meramente aparente o antagonismo entre esta doutrina e a dogmática. Mais adiante mostraremos que talvez seja muito menor do que se pensa a distância que, da doutrina das vidas sucessivas, separa a religião e que a esta não faria aquela doutrina maior mal do que lhe fizeram as descobertas do movimento da Terra e dos períodos geológicos, as quais, à primeira vista, pareceram desmentir os textos sagrados. Demais, o princípio da reencarnação ressalta de muitas passagens das Escrituras, achando-se especialmente formulado, de modo explícito, no Evangelho: "Quando desciam da montanha (depois da transfiguração), Jesus lhes fez esta recomendação: Não faleis a ninguém do que acabastes de ver, até que o Filho do homem tenha ressuscitado, dentre os mortos. Perguntaram-lhe então seus discípulos: Por que dizem os escribas ser preciso que primeiro venha Elias? Respondeu-lhes Jesus: É certo que Elias há de vir e que restabelecerá todas as coisas. Mas, eu vos declaro que Elias já veio, e eles não o conheceram e o fizeram sofrer como entenderam. Do mesmo modo darão a morte ao Filho do homem. Compreenderam então seus discípulos que era de João Batista que ele lhes falava." (São Mateus, cap. 17) Pois que João Batista fora Elias, houve reencarnação do Espírito ou da alma de Elias no corpo de João Batista. Em suma, como quer que opinemos acerca da reencarnação, quer a aceitemos, quer não, isso não constituirá motivo para que deixemos de sofrê-la, desde que ela exista, malgrado a todas as crenças em contrário. O essencial está em que o ensino dos Espíritos é eminentemente cristão; apóia-se na imortalidade da alma, nas penas e recompensas futuras, na justiça de Deus, no livre-arbítrio do homem, na moral do Cristo. Logo, não é anti-religioso. Temos raciocinado, abstraindo, como dissemos, de qualquer ensinamento espírita que, para certas pessoas, carece de autoridade. Não é somente porque veio dos Espíritos que nós e tantos outros nos fizemos adeptos da pluralidade das existências. É porque essa doutrina nos pareceu a mais lógica e porque só ela resolve questões até então insolúveis. Ainda quando fosse da autoria de um simples mortal, tê-la-íamos igualmente adotado e não houvéramos hesitado um segundo mais em renunciar às idéias que esposávamos. Em sendo demonstrado o erro, muito mais que perder do que ganhar tem o amor-próprio, com o se obstinar na sustentação de uma idéia falsa. Assim também, tê-la-íamos repelido, mesmo que provindo dos Espíritos, se nos parecera contrária à razão, como repelimos muitas outras, pois sabemos, por experiência, que não se deve aceitar cegamente tudo o que venha deles, da mesma forma que se não deve adotar às cegas tudo o que proceda dos homens. O melhor título que, ao nosso ver, recomenda a idéia da reencarnação é o de ser, antes de tudo, lógica. Outro, no entanto, ela apresenta: o de a confirmarem os fatos, fatos positivos e por bem dizer, materiais, que um estudo atento e criterioso revela a quem se dê ao trabalho de observar com paciência e perseverança e diante dos quais não há mais lugar para a dúvida. Quando esses fatos se houverem vulgarizado, como os da formação e do movimento da Terra, forçoso será que todos se rendam à evidência e os que se lhes colocaram em oposição ver-se-ão constrangidos a desdizer-se. Reconheçamos, portanto, em resumo, que só a doutrina da pluralidade das existências explica o que, sem ela, se mantém inexplicável; que é altamente consoladora e conforme à mais rigorosa justiça; que constitui para o homem a âncora de salvação que Deus, por misericórdia, lhe concedeu. As próprias palavras de Jesus não permitem dúvida a tal respeito. Eis o que se lê no Evangelho de São João, capítulo 3: 3. Respondendo a Nicodemos, disse Jesus: Em verdade, em verdade te digo que, se um homem não nascer de novo, não poderá ver o reino de Deus. 4. Disse-lhe Nicodemos: Como pode um homem nascer já estando velho? Pode tornar ao ventre de sua mãe para nascer segunda vez? 5. Respondeu Jesus: Em verdade, em verdade te digo que, se um homem não renascer da água e do Espírito, não poderá entrar no reino de Deus. O que é nascido da carne é carne e o que é nascido do Espírito é Espírito. Não te admires de que eu te tenha dito: é necessário que torneis a nascer. (Ver, adiante, o parágrafo "Ressurreição da carne", nº 1010.) 110 – Allan Kar dec', 'rascunho'),
  (223, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'A alma reencarna logo depois de se haver separado do corpo?', 'Algumas vezes reencarna imediatamente, porém de ordinário só o faz depois de intervalos mais ou menos longos. Nos mundos superiores, a reencarnação é quase sempre imediata. Sendo aí menos grosseira a matéria corporal, o Espírito, quando encarnado nesses mundos, goza quase que de todas as suas faculdades de Espírito, sendo o seu estado normal o dos sonâmbulos lúcidos entre vós.', 'rascunho'),
  (224, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Que é a alma no intervalo das encarnações?', 'Espírito errante, que aspira a novo destino, que espera." a) — Quanto podem durar esses intervalos? "Desde algumas horas até alguns milhares de séculos. Propriamente falando, não há extremo limite estabelecido para o estado de erraticidade, que pode prolongar-se muitíssimo, mas que nunca é perpétuo. Cedo ou tarde, o Espírito terá que volver a uma existência apropriada a purificá-lo das máculas de suas existências precedentes." b) — Essa duração depende da vontade do Espírito, ou lhe pode ser imposta como expiação? "É uma conseqüência do livre-arbítrio. Os Espíritos sabem perfeitamente o que fazem. Mas, também, para alguns, constitui uma punição que Deus lhes inflige. Outros pedem que ela se prolongue, a fim de continuarem estudos que só na condição de Espírito livre podem efetuar-se com proveito.', 'rascunho'),
  (225, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'A erraticidade é, por si só, um sinal de inferioridade dos Espíritos?', 'Não, porquanto há Espíritos errantes de todos os graus. A encarnação é um estado transitório, já o dissemos. O Espírito se acha no seu estado normal, quando liberto da matéria.', 'rascunho'),
  (226, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Poder-se-á dizer que são errantes todos os Espíritos que não estão encarnados?', 'Sim, com relação aos que tenham de reencarnar. Não são errantes, porém, os Espíritos puros, os que chegaram à perfeição. Esses se encontram no seu estado definitivo." No tocante às qualidades íntimas, os Espíritos são de diferentes ordens, ou graus, pelos quais vão passando sucessivamente, à medida que se purificam Com relação ao estado em que se acham, podem ser: encarnados, isto é, ligados a um corpo; errantes, isto é, sem corpo material e aguardando nova encarnação para se melhorarem; Espíritos puros, isto é, perfeitos, não precisando mais de encarnação.', 'rascunho'),
  (227, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'De que modo se instruem os Espíritos errantes? Certo não o fazem do mesmo modo que nós outros?', 'Estudam e procuram meios de elevar-se. Vêem, observam o que ocorre nos lugares aonde vão; ouvem os discursos dos homens doutos e os conselhos dos Espíritos mais elevados e tudo isso lhes incute idéias que antes não tinham.', 'rascunho'),
  (228, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Conservam os Espíritos algumas de suas paixões humanas?', 'Com o invólucro imaterial os Espíritos elevados deixam as paixões más e só guardam a do bem. Quanto aos Espíritos inferiores, esses as conservam, pois do contrário pertenceriam à primeira ordem.', 'rascunho'),
  (229, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Por que, deixando a Terra, não deixam aí os Espíritos todas as más paixões, uma vez que lhes reconhecem os inconvenientes?', 'Vês nesse mundo pessoas excessivamente invejosas. Imaginas que, mal o deixam, perdem esse defeito? Acompanha os que da Terra partem, sobretudo os que alimentaram paixões bem acentuadas, uma espécie de atmosfera que os envolve, conservando-lhes o que têm de mau, por não se achar o Espírito inteiramente desprendido da matéria. Só por momentos ele entrevê a verdade, que assim lhe aparece como que para mostrar-lhe o bom caminho.', 'rascunho'),
  (230, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Na erraticidade, o Espírito progride?', 'Pode melhorar-se muito, tais sejam a vontade e o desejo que tenha de consegui-lo. Todavia, na existência corporal é que põe em prática as idéias que adquiriu.', 'rascunho'),
  (231, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'São felizes ou desgraçados os Espíritos errantes?', 'Mais ou menos, conforme seus méritos. Sofrem por efeito das paixões cuja essência conservaram, ou são felizes, de conformidade com o grau de desmaterialização a que hajam chegado. Na erraticidade, o Espírito percebe o que lhe falta para ser mais feliz e, desde então, procura os meios de alcançá-lo. Nem 112 – Allan Kar dec sempre, porém, lhe é permitido reencarnar como fora de seu agrado, representando isso, para ele, uma punição.', 'rascunho'),
  (232, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Podem os Espíritos errantes ir a todos os mundos?', 'Conforme. Pelo simples fato de haver deixado o corpo, o Espírito não se acha completamente desprendido da matéria e continua a pertencer ao mundo onde acabou de viver, ou a outro do mesmo grau, a menos que, durante a vida, se tenha elevado, o que, aliás, constitui o objetivo para que devem tender seus esforços, pois, do contrário, nunca se aperfeiçoaria. Pode, no entanto, ir a alguns mundos superiores, mas na qualidade de estrangeiro. A bem dizer, consegue apenas entrevê- los, donde lhe nasce o desejo de melhorar-se, para ser digno da felicidade de que gozam os que os habitam, para ser digno também de habitá-los mais tarde.', 'rascunho'),
  (233, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Os Espíritos já purificados descem aos mundos inferiores?', 'Fazem-no freqüentemente, com o fim de auxiliar-lhes o progresso. A não ser assim, esses mundos estariam entregues a si mesmos, sem guias para dirigi-los.', 'rascunho'),
  (234, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Há, de fato, como já foi dito, mundos que servem de estações ou pontos de repouso aos Espíritos errantes?', 'Sim, há mundos particularmente destinados aos seres errantes, mundos que lhes podem servir de habitação temporária, espécies de bivaques, de campos onde descansem de uma demasiado longa erraticidade, estado este sempre um tanto penoso. São, entre os outros mundos, posições intermédias, graduadas de acordo com a natureza dos Espíritos que a elas podem ter acesso e onde eles gozam de maior ou menor bem-estar." a) — Os Espíritos que habitam esses mundos podem deixá-los livremente? "Sim, os Espíritos que se encontram nesses mundos podem deixá-los, a fim de irem para onde devam ir. Figurai-os como bandos de aves que pousam numa ilha, para aí aguardarem que se lhes refaçam as forças, a fim de seguirem seu destino.', 'rascunho'),
  (235, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Enquanto permanecem nos mundos transitórios, os Espíritos progridem?', 'Certamente. Os que vão a tais mundos levam o objetivo de se instruírem e de poderem mais facilmente obter permissão para passar a outros lugares melhores e chegar à perfeição que os eleitos atingem.', 'rascunho'),
  (236, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Pela sua natureza especial, os mundos transitórios se conservam perpetuamente destinados aos Espíritos errantes?', 'Não, a condição deles é meramente temporária." a) — Esses mundos são ao mesmo tempo habitados por seres corpóreos? "Não; estéril é neles a superfície. Os que os habitam de nada precisam." b) — É permanente essa esterilidade e decorre da natureza especial que apresentam? "Não; são estéreis transitoriamente." c) — Os mundos dessa categoria carecem então de belezas naturais? "A Natureza reflete as belezas da imensidade, que não são menos admiráveis do que aquilo a que dais o nome de belezas naturais." d) — Sendo transitório o estado de semelhantes mundos, a Terra pertencerá algum dia ao número deles? "Já pertenceu." e) — Em que época? "Durante a sua formação." Nada é inútil em a Natureza; tudo tem um fim, uma destinação. Em lugar algum há o vazio; tudo é habitado, há vida em toda parte. Assim, durante a dilatada sucessão dos séculos que passaram antes do aparecimento do homem na Terra, durante os lentos períodos de transição que as camadas geológicas atestam, antes mesmo da formação dos primeiros seres orgânicos, naquela massa informe, naquele árido caos, onde os elementos se achavam em confusão, não havia ausência de vida. Seres isentos das nossas necessidades, das nossas sensações físicas, lá encontravam refúgio. Quis Deus que, mesmo assim, ainda imperfeita, a Terra servisse para alguma coisa. Quem ousaria afirmar que, entre os milhares de mundos que giram na imensidade, um só, um dos menores, perdido no seio da multidão infinita deles, goza do privilégio exclusivo de ser povoado? Qual então a utilidade dos demais? Tê-los-ia Deus feito unicamente para nos recrearem a vista? Suposição absurda, incompatível com a sabedoria que esplende em todas as suas obras e inadmissível desde que ponderemos na existência de todos os que não podemos perceber. Ninguém contestará que, nesta idéia da existência de mundos ainda impróprios para a vida material e, não obstante, já povoados de seres vivos apropriados a tal meio, há qualquer coisa de grande e sublime, em que talvez se encontre a solução de mais de um problema.', 'rascunho'),
  (237, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Uma vez de volta ao mundo dos Espíritos, conserva a alma as percepções que tinha quando na Terra?', 'Sim, além de outras de que aí não dispunha, porque o corpo, qual véu sobre elas lançado, as obscurecia. A inteligência é um atributo, que tanto mais livremente se manifesta no Espírito, quanto menos entraves tenha que vencer.', 'rascunho'),
  (238, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'São ilimitadas as percepções e os conhecimentos dos Espíritos? Numa palavra: eles sabem tudo?', 'Quanto mais se aproximam da perfeição, tanto mais sabem. Se são Espíritos superiores, sabem muito. Os Espíritos inferiores são mais ou menos ignorantes acerca de tudo.', 'rascunho'),
  (239, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Conhecem os Espíritos o princípio das coisas? 114 – Allan Kar dec', 'Conforme a elevação e a pureza que hajam atingido. Os de ordem inferior não sabem mais do que os homens.', 'rascunho'),
  (240, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'A duração, os Espíritos a compreendem como nós?', 'Não e daí vem que nem sempre nos compreendeis, quando se trata de determinar datas ou épocas." Os Espíritos vivem fora do tempo como o compreendemos. A duração, para eles, deixa, por assim dizer, de existir. Os séculos, para nós tão longos, não passam, aos olhos deles, de instantes que se movem na eternidade, do mesmo modo que os relevos do solo se apagam e desaparecem para quem se eleva no espaço.', 'rascunho'),
  (241, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Os Espíritos fazem do presente mais precisa e exata idéia do que nós?', 'Do mesmo modo que aquele, que vê bem, faz mais exata idéia das coisas do que o cego. Os Espíritos vêem o que não vedes. Tudo apreciam, pois, diversamente do modo por que o fazeis. Mas, também isso depende da elevação deles.', 'rascunho'),
  (242, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Como é que os Espíritos têm conhecimento do passado? E esse conhecimento lhes é ilimitado?', 'O passado, quando com ele nos ocupamos, é presente. Verifica-se então, precisamente, o que se passa contigo quando recordas qualquer coisa que te impressionou no curso do teu exílio. Simplesmente, como já nenhum véu material nos tolda a inteligência, lembramo-nos mesmo daquilo que se te apagou da memória. Mas, nem tudo os Espíritos sabem, a começar pela sua própria criação.', 'rascunho'),
  (243, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'E o futuro, os Espíritos o conhecem?', 'Ainda isto depende da elevação que tenham conquistado. Muitas vezes, apenas o entrevêem, porém nem sempre lhes é permitido revelá-lo. Quando o vêem, parece-lhes presente. À medida que se aproxima de Deus, tanto mais claramente o Espírito descortina o futuro. Depois da morte, a alma vê e apreende num golpe de vista suas passadas migrações, mas não pode ver o que Deus lhe reserva. Para que tal aconteça, preciso é que, ao cabo de múltiplas existências, se haja integrado nele." a) — Os Espíritos que alcançaram a perfeição absoluta têm conhecimento completo do futuro? "Completo não se pode dizer, por isso que só Deus é soberano Senhor e ninguém o pode igualar.', 'rascunho'),
  (244, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Os Espíritos vêem a Deus?', 'Só os Espíritos superiores o vêem e compreendem. Os inferiores o sentem e adivinham." a) — Quando um Espírito inferior diz que Deus lhe proíbe ou permite uma coisa, como sabe que isso lhe vem dele? "Ele não vê a Deus, mas sente a sua soberania e, quando não deva ser feita alguma coisa ou dita uma palavra, percebe, como por intuição, a proibição de fazê-la ou dizê-la. Não tendes vós mesmos pressentimentos, que se vos afiguram avisos secretos, para fazerdes, ou não, isto ou aquilo? O mesmo nos acontece, se bem que em grau mais alto, pois compreendes que, sendo mais sutil do que as vossas a essência dos Espíritos, podem estes receber melhor as advertências divinas." b) — Deus transmite diretamente a ordem ao Espírito, ou por intermédio de outros Espíritos? "Ela não lhe vem direta de Deus. Para se comunicar com Deus, é-lhe necessário ser digno disso. Deus lhe transmite suas ordens por intermédio dos Espíritos imediatamente superiores em perfeição e instrução.', 'rascunho'),
  (245, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'O Espírito tem circunscrita a visão como os seres corpóreos?', 'Não, ela reside em todo ele.', 'rascunho'),
  (246, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Precisam da luz para ver?', 'Vêem por si mesmos, sem precisarem de luz exterior. Para os Espíritos, não há trevas, salvo as em que podem achar-se por expiação.', 'rascunho'),
  (247, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Para verem o que se passa em dois pontos diferentes, precisam transportar-se a esses pontos? Podem, por exemplo, ver simultaneamente nos dois hemisférios do globo?', 'Como o Espírito se transporta aonde queira, com a rapidez do pensamento, pode-se dizer que vê em toda parte ao mesmo tempo. Seu pensamento é suscetível de irradiar, dirigindo-se a um tempo para muitos pontos diferentes, mas esta faculdade depende da sua pureza. Quanto menos puro é o Espírito, tanto mais limitada tem a visão. Só os Espíritos superiores podem com a vista abranger um conjunto." No Espírito, a faculdade de ver é uma propriedade inerente à sua natureza e que reside em todo o seu ser, como a luz reside em todas as partes de um corpo luminoso. É uma espécie de lucidez universal que se estende a tudo, que abrange simultaneamente o espaço, os tempos e as coisas, lucidez para a qual não há trevas, nem obstáculos materiais. Compreende-se que deva ser assim. No homem, a visão se dá pelo funcionamento de um órgão que a luz impressiona. Daí se segue que, não havendo luz, o homem fica na obscuridade. No Espírito, como a faculdade de ver constitui um atributo seu, abstração feita de qualquer agente exterior, a visão independe da luz. (Veja-se: Ubiqüidade, nº 92.)', 'rascunho'),
  (248, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'O Espírito vê as coisas tão distintamente como nós?', 'Mais distintamente, pois que sua vista penetra onde a vossa não pode penetrar. Nada a obscurece.', 'rascunho'),
  (249, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Percebe os sons?', 'Sim, percebe mesmo sons imperceptíveis para os vossos sentidos obtusos." a) — No Espírito, a faculdade de ouvir está em todo ele, como a de ver? "Todas as percepções constituem atributos do Espírito e lhe são inerentes ao ser. Quando o reveste um corpo material, elas só lhe chegam pelo conduto dos 116 – Allan Kar dec órgãos. Deixam, porém, de estar localizadas, em se achando ele na condição de Espírito livre.', 'rascunho'),
  (250, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Constituindo elas atributos próprios do Espírito, ser-lhe-á possível subtrair-se às percepções?', 'O Espírito unicamente vê e ouve o que quer. Dizemos isto de um ponto de vista geral e, em particular, com referência aos Espíritos elevados, porquanto os imperfeitos muitas vezes ouvem e vêem, a seu mau grado, o que lhes possa ser útil ao aperfeiçoamento.', 'rascunho'),
  (251, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'São sensíveis à música os Espíritos?', 'Aludes à música terrena? Que é ela comparada à música celeste? a esta harmonia de que nada na Terra vos pode dar idéia? Uma está para a outra como o canto do selvagem para uma doce melodia. Não obstante, Espíritos vulgares podem experimentar certo prazer em ouvir a vossa música, por lhes não ser dado ainda compreenderem outra mais sublime. A música possui infinitos encantos para os Espíritos, por terem eles muito desenvolvidas as qualidades sensitivas. Refiro-me à música celeste, que é tudo o que de mais belo e delicado pode a imaginação espiritual conceber.', 'rascunho'),
  (252, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'São sensíveis, os Espíritos, às magnificências da Natureza?', 'Tão diferentes são as belezas naturais dos mundos, que longe estamos de as conhecer. Sim, os Espíritos são sensíveis a essas belezas, de acordo com as aptidões que tenham para as apreciar e compreender. Para os Espíritos elevados, há belezas de conjunto que, por assim dizer, apagam as das particularidades.', 'rascunho'),
  (253, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Os Espíritos experimentam as nossas necessidades e sofrimentos físicos?', 'Eles os conhecem, porque os sofreram, não os experimentam, porém, materialmente, com vós outros: são Espíritos.', 'rascunho'),
  (254, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'E a fadiga, a necessidade de repouso, experimentam-nas?', 'Não podem sentir a fadiga, como a entendeis; conseguintemente, não precisam de descanso corporal, como vós, pois que não possuem órgãos cujas forças devam ser reparadas. O Espírito, entretanto, repousa, no sentido de não estar em constante atividade. Ele não atua materialmente. Sua ação é toda intelectual e inteiramente moral o seu repouso. Quer isto dizer que momentos há em que o seu pensamento deixa de ser tão ativo quanto de ordinário e não se fixa em qualquer objeto determinado. É um verdadeiro repouso, mas de nenhum modo comparável ao do corpo. A espécie de fadiga que os Espíritos são suscetíveis de sentir guarda relação com a inferioridade deles. Quanto mais elevados sejam, tanto menos precisarão de repousar.', 'rascunho'),
  (255, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Quando um Espírito diz que sofre, de que natureza é o seu sofrimento?', 'Angústias morais, que o torturam mais dolorosamente do que todos os sofrimentos físicos.', 'rascunho'),
  (256, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Como é então que alguns Espíritos se têm queixado de sofrer frio ou calor?', 'É reminiscência do que padecem durante a vida, reminiscência não raro tão aflitiva quanto a realidade. Muitas vezes, no que eles assim dizem apenas há uma comparação mediante a qual, em falta de coisa melhor, procuram exprimir a situação em que se acham. Quando se lembram do corpo que revestiram, têm impressão semelhante à de uma pessoa que, havendo tirado o manto que a envolvia, julga, passado algum tempo, que ainda o traz sobre os ombros.', 'rascunho'),
  (257, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'O corpo é o instrumento da dor. Se não é a causa primária desta é, pelo menos, a causa imediata. A alma tem a percepção da dor: essa percepção é o efeito. A lembrança que da dor a alma conserva pode ser muito penosa, mas não pode ter ação física. De fato, nem o frio, nem o calor são capazes de desorganizar os tecidos da alma, que não é suscetível de congelar-se, nem de queimar-se. Não vemos todos os dias a recordação ou a apreensão de um mal físico produzirem o efeito desse mal, como se real fora? Não as vemos até causar a morte? Toda gente sabe que aqueles a quem se amputou um membro costumam sentir dor no membro que lhes falta. Certo que aí não está a sede, ou, sequer, o ponto de partida da dor. O que há, apenas, é que o cérebro guardou desta a impressão. Lícito, portanto, será admitir- se que coisa análoga ocorra nos sofrimentos do Espírito após a morte. Um estudo aprofundado do perispírito, que tão importante papel desempenha em todos os fenômenos espíritas; nas aparições vaporosas ou tangíveis; no estado em que o Espírito vem a encontrar-se por ocasião da morte; na idéia, que tão freqüentemente manifesta, de que ainda está vivo; nas situações tão comoventes que nos revelam os dos suicidas, dos supliciados, dos que se deixaram absorver pelos gozos materiais; e inúmeros outros fatos, muita luz lançaram sobre esta questão, dando lugar a explicações que passamos a resumir. O perispírito é o laço que à matéria do corpo prende o Espírito, que o tira do meio ambiente, do fluido universal. Participa ao mesmo tempo da eletricidade, do fluido magnético e, até certo ponto, da matéria inerte. Poder-se-ia dizer que é a quintessência da matéria. É o princípio da vida orgânica, porém não o da vida intelectual, que reside no Espírito. É, além disso, o agente das sensações exteriores. No corpo, os órgãos, servindo-lhes de condutos, localizam essas sensações. Destruído o corpo, elas se tornam gerais. Daí o Espírito não dizer que sofre mais da cabeça do que dos pés, ou vice-versa. Não se confundam, porém, as sensações do perispírito, que se tornou independente, com as do corpo. Estas últimas só por termo de comparação as podemos tomar e não por analogia. Liberto do corpo, o Espírito pode sofrer, mas esse sofrimento não é corporal, embora não seja exclusivamente moral, como o remorso, pois que ele se queixa de frio e calor. Também não sofre mais no inverno do que no verão: temo-los visto atravessar chamas, sem experimentarem qualquer dor. Nenhuma impressão lhes causa, conseguintemente, a temperatura. A dor que sentem não é, pois, uma dor física propriamente dita: é um vago sentimento íntimo, que o próprio Espírito nem sempre compreende bem, precisamente porque a dor não se acha localizada e porque não a 118 – Allan Kar dec produzem agentes exteriores; é mais uma reminiscência do que uma realidade, reminiscência, porém, igualmente penosa. Algumas vezes, entretanto, há mais do que isso, como vamos ver. Ensina-nos a experiência que, por ocasião da morte, o perispírito se desprende mais ou menos lentamente do corpo; que, durante os primeiros minutos depois da desencarnação, o Espírito não encontra explicação para a situação em que se acha. Crê não estar morto, por isso que se sente vivo; vê a um lado o corpo, sabe que lhe pertence, mas não compreende que esteja separado dele. Essa situação dura enquanto haja qualquer ligação entre o corpo e o perispírito. Disse-nos, certa vez, um suicida:', 'Não, não estou morto." E acrescentava: No entanto, sinto os vermes a me roerem. Ora, indubitavelmente, os vermes não lhe roíam o perispírito e ainda menos o Espírito; roíam-lhe apenas o corpo. Como, porém, não era completa a separação do corpo e do perispírito, uma espécie de repercussão moral se produzia, transmitindo ao Espírito o que estava ocorrendo no corpo. Repercussão talvez não seja o termo próprio, porque pode induzir à suposição de um efeito muito material. Era antes a visão do que se passava com o corpo, ao qual ainda o conservava ligado o perispírito, o que lhe causava a ilusão, que ele tomava por realidade. Assim, pois, não haveria no caso uma reminiscência, porquanto ele não fora, em vida, roído pelos vermes: havia o sentimento de um fato da atualidade. Isto mostra que deduções se podem tirar dos fatos, quando atentamente observados. Durante a vida, o corpo recebe impressões exteriores e as transmite ao Espírito por intermédio do perispírito, que constitui, provavelmente, o que se chama fluido nervoso. Uma vez morto, o corpo nada mais sente, por já não haver nele Espírito, nem perispírito. Este, desprendido do corpo, experimenta a sensação, porém, como já não lhe chega por um conduto limitado, ela se lhe torna geral. Ora, não sendo o perispírito, realmente, mais do que simples agente de transmissão, pois que no Espírito é que está a consciência, lógico será deduzir-se que, se pudesse existir perispírito sem Espírito, aquele nada sentiria, exatamente como um corpo que morreu. Do mesmo modo, se o Espírito não tivesse perispírito, seria inacessível a toda e qualquer sensação dolorosa. É o que se dá com os Espíritos completamente purificados. Sabemos que quanto mais eles se purificam, tanto mais etérea se torna a essência do perispírito, donde se segue que a influência material diminui à medida que o Espírito progride, isto é, à medida que o próprio perispírito se torna menos grosseiro. Mas, dir-se-á, desde que pelo perispírito é que as sensações agradáveis, da mesma forma que as desagradáveis, se transmitem ao Espírito, sendo o Espírito puro inacessível a umas, deve sê-lo igualmente às outras. Assim é, de fato, com relação às que provêm unicamente da influência da matéria que conhecemos. O som dos nossos instrumentos, o perfume das nossas flores nenhuma impressão lhe causam. Entretanto, ele experimenta sensações íntimas, de um encanto indefinível, das quais idéia alguma podemos formar, porque, a esse respeito, somos quais cegos de nascença diante da luz. Sabemos que isso é real; mas, por que meio se produz? Até lá não vai a nossa ciência. Sabemos que no Espírito há percepção, sensação, audição, visão; que essas faculdades são atributos do ser todo e não, como no homem, de uma parte apenas do ser; mas, de que modo ele as tem? Ignoramo-lo. Os próprios Espíritos nada nos podem informar sobre isso, por inadequada a nossa linguagem a exprimir idéias que não possuímos, precisamente como o é, por falta de termos próprios, a dos selvagens, para traduzir idéias referentes às nossas artes, ciências e doutrinas filosóficas. Dizendo que os Espíritos são inacessíveis às impressões da matéria que conhecemos, referimo-nos aos Espíritos muito elevados, cujo envoltório etéreo não encontra analogia neste mundo. Outro tanto não acontece com os de perispírito mais denso, os quais percebem os nossos sons e odores, não, porém, apenas por uma parte limitada de suas individualidades, conforme lhes sucedia quando vivos. Pode-se dizer que, neles, as vibrações moleculares se fazem sentir em todo o ser e lhes chegam assim ao sensorium commune, que é o próprio Espírito, embora de modo diverso e talvez, também, dando uma impressão diferente, o que modifica a percepção. Eles ouvem o som da nossa voz, entretanto nos compreendem sem o auxílio da palavra, somente pela transmissão do pensamento. Em apoio do que dizemos há o fato de que essa penetração é tanto mais fácil, quanto mais desmaterializado está o Espírito. Pelo que concerne à vista, essa, para o Espírito, independe da luz, qual a temos. A faculdade de ver é um atributo essencial da alma, para quem a obscuridade não existe. É, contudo, mais extensa, mais penetrante nas mais purificadas. A alma, ou o Espírito, tem, pois, em si mesma, a faculdade de todas as percepções. Estas, na vida corpórea, se obliteram pela grosseria dos órgãos do corpo; na vida extracorpórea se vão desanuviando, à proporção que o invólucro semimaterial se eteriza. Haurido do meio ambiente, esse invólucro varia de acordo com a natureza dos mundos. Ao passarem de um mundo a outro, os Espíritos mudam de envoltório, como nós mudamos de roupa, quando passamos do inverno ao verão, ou do pólo ao equador. Quando vêm visitar-nos, os mais elevados se revestem do perispírito terrestre e então suas percepções se produzem como no comum dos Espíritos. Todos, porém, assim os inferiores como os superiores, não ouvem, nem sentem, senão o que queiram ouvir ou sentir. Não possuindo órgãos sensitivos, eles podem, livremente, tornar ativas ou nulas suas percepções. Uma só coisa são obrigados a ouvir — os conselhos dos Espíritos bons. A vista, essa é sempre ativa; mas, eles podem fazer-se invisíveis uns aos outros. Conforme a categoria que ocupem, podem ocultar-se dos que lhes são inferiores, porém não dos que lhes são superiores. Nos primeiros instantes que se seguem à morte, a visão do Espírito é sempre turbada e confusa. Aclara-se, à medida que ele se desprende, e pode alcançar a nitidez que tinha durante a vida terrena, independentemente da possibilidade de penetrar através dos corpos que nos são opacos. Quanto à sua extensão através do espaço indefinito, do futuro e do passado, depende do grau de pureza e de elevação do Espírito. Objetarão, talvez: toda esta teoria nada tem de tranqüilizadora. Pensávamos que, uma vez livres do nosso grosseiro envoltório, instrumento das nossas dores, não mais sofreríamos e eis nos informais de que ainda sofreremos. Desta ou daquela forma, será sempre sofrimento. Ah! sim, pode dar-se que continuemos a sofrer, e muito, e por longo tempo, mas também que deixemos de sofrer, até mesmo desde o instante em que se nos acabe a vida corporal. Os sofrimentos deste mundo independem, algumas vezes, de nós; muito mais vezes, contudo, são devidos à nossa vontade. Remonte cada um à origem deles 120 – Allan Kar dec e verá que a maior parte de tais sofrimentos são efeitos de causas que lhe teria sido possível evitar. Quantos males, quantas enfermidades não deve o homem aos seus excessos, à sua ambição, numa palavra: às suas paixões? Aquele que sempre vivesse com sobriedade, que de nada abusasse, que fosse sempre simples nos gostos e modesto nos desejos, a muitas tribulações se forraria. O mesmo se dá com o Espírito. Os sofrimentos por que passa são sempre a conseqüência da maneira por que viveu na Terra. Certo já não sofrerá mais de gota, nem de reumatismo; no entanto, experimentará outros sofrimentos que nada ficam a dever àqueles. Vimos que seu sofrer resulta dos laços que ainda o prendem à matéria; que quanto mais livre estiver da influência desta, ou, por outra, quanto mais desmaterializado se achar, menos dolorosas sensações experimentará. Ora, está nas suas mãos libertar- se de tal influência desde a vida atual. Ele tem o livre-arbítrio, tem, por conseguinte, a faculdade de escolha entre o fazer e o não fazer. Dome suas paixões animais; não alimente ódio, nem inveja, nem ciúme, nem orgulho; não se deixe dominar pelo egoísmo; purifique-se, nutrindo bons sentimentos; pratique o bem; não ligue às coisas deste mundo importância que não merecem; e, então, embora revestido do invólucro corporal, já estará depurado, já estará liberto do jugo da matéria e, quando deixar esse invólucro, não mais lhe sofrerá a influência. Nenhuma recordação dolorosa lhe advirá dos sofrimentos físicos que haja padecido; nenhuma impressão desagradável eles lhe deixarão, porque apenas terão atingido o corpo e não a alma. Sentir-se-á feliz por se haver libertado deles e a paz da sua consciência o isentará de qualquer sofrimento moral. Interrogamos, aos milhares, Espíritos que na Terra pertenceram a todas as classes da sociedade, ocuparam todas as posições sociais; estudamo-los em todos os períodos da vida espírita, a partir do momento em que abandonaram o corpo; acompanhamo-los passo a passo na vida de além--túmulo, para observar as mudanças que se operavam neles, nas suas idéias, nos seus sentimentos e, sob esse aspecto, não foram os que aqui se contaram entre os homens mais vulgares os que nos proporcionaram menos preciosos elementos de estudo. Ora, notamos sempre que os sofrimentos guardavam relação com o proceder que eles tiveram e cujas conseqüências experimentavam; que a outra vida é fonte de inefável ventura para os que seguiram o bom caminho. Deduz-se daí que, aos que sofrem, isso acontece porque o quiseram; que, portanto, só de si mesmos se devem queixar, quer no outro mundo, quer neste.', 'rascunho'),
  (258, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Quando na erraticidade, antes de começar nova existência corporal, tem o Espírito consciência e previsão do que lhe sucederá no curso da vida terrena?', 'Ele próprio escolhe o gênero de provas por que há de passar e nisso consiste o seu livre-arbítrio." a) — Não é Deus, então, quem lhe impõe as tribulações da vida, como castigo? "Nada ocorre sem a permissão de Deus, porquanto foi Deus quem estabeleceu todas as leis que regem o Universo. Ide agora perguntar por que decretou ele esta lei e não aquela. Dando ao Espírito a liberdade de escolher, Deus lhe deixa a inteira responsabilidade de seus atos e das conseqüências que estes tiverem. Nada lhe estorva o futuro; abertos se lhe acham, assim, o caminho do bem, como o do mal. Se vier a sucumbir, restar-lhe-á a consolação de que nem tudo se lhe acabou e que a bondade divina lhe concede a liberdade de recomeçar o que foi malfeito. Demais, cumpre se distinga o que é obra da vontade de Deus do que o é da do homem. Se um perigo vos ameaça, não fostes vós quem o criou e sim Deus. Vosso, porém, foi o desejo de a ele vos expordes, por haverdes visto nisso um meio de progredirdes, e Deus o permitiu.', 'rascunho'),
  (259, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Do fato de pertencer ao Espírito a escolha do gênero de provas que deva sofrer, seguir-se-á que todas as tribulações que experimentamos na vida nós as previmos e buscamos?', 'Todas, não, porque não escolhestes e previstes tudo o que vos sucede no mundo, até às mínimas coisas. Escolhestes apenas o gênero das provações. As particularidades correm por conta da posição em que vos achais; são, muitas vezes, conseqüências das vossas próprias ações. Escolhendo, por exemplo, nascer entre malfeitores, sabia o Espírito a que arrastamentos se expunha; ignorava, porém, quais os atos que viria a praticar. Esses atos resultam do exercício da sua vontade, ou do seu livre-arbítrio. Sabe o Espírito que, escolhendo tal caminho, terá que sustentar lutas de determinada espécie; sabe, portanto, de que natureza serão as vicissitudes que se lhe depararão, mas ignora se se verificará este ou aquele êxito. Os acontecimentos secundários se originam das circunstâncias e da força mesma das coisas. Previstos só são os fatos principais, os que influem no destino. Se tomares uma estrada cheia de sulcos profundos, sabes que terás de andar cautelosamente, porque há muitas probabilidades de caíres; ignoras, contudo, em que ponto cairás e bem pode suceder que não caias, se fores bastante prudente. Se, ao percorreres uma rua, uma telha te cair na cabeça, não creias que estava escrito, segundo vulgarmente se diz.', 'rascunho'),
  (260, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Como pode o Espírito desejar nascer entre gente de má vida?', 'Forçoso é que seja posto num meio onde possa sofrer a prova que pediu. Pois bem! É necessário que haja analogia. Para lutar contra o instinto do roubo, preciso é que se ache em contacto com gente dada à prática de roubar." a) — Assim, se não houvesse na Terra gente de maus costumes, o Espírito não encontraria aí meio apropriado ao sofrimento de certas provas? "E seria isso de lastimar-se? É o que ocorre nos mundos superiores, onde o mal não penetra. Eis por que, nesses mundos, só há Espíritos bons. Fazei que em breve o mesmo se dê na Terra.', 'rascunho'),
  (261, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Nas provações por que lhe cumpre passar para atingir a perfeição, tem o Espírito que sofrer tentações de todas as naturezas? Tem que se achar em todas as circunstâncias que possam excitar-lhe o orgulho, a inveja, a avareza, a sensualidade, etc.? 122 – Allan Kar dec', 'Certo que não, pois bem sabeis haver Espíritos que desde o começo tomam um caminho que os exime de muitas provas. Aquele, porém, que se deixa arrastar para o mau caminho, corre todos os perigos que o inçam. Pode um Espírito, por exemplo, pedir a riqueza e ser-lhe esta concedida. Então, conforme o seu caráter, poderá tornar-se avaro ou pródigo, egoísta ou generoso, ou ainda lançar-se a todos os gozos da sensualidade. Daí não se segue, entretanto, que haja de forçosamente passar por todas estas tendências.', 'rascunho'),
  (262, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Como pode o Espírito, que, em sua origem, é simples, ignorante e carecido de experiência, escolher uma existência com conhecimento de causa e ser responsável por essa escolha?', 'Deus lhe supre a inexperiência, traçando-lhe o caminho que deve seguir, como fazeis com a criancinha. Deixa-o, porém, pouco a pouco, à medida que o seu livre-arbítrio se desenvolve, senhor de proceder à escolha e só então é que muitas vezes lhe acontece extraviar-se, tomando o mau caminho, por desatender os conselhos dos bons Espíritos. A isso é que se pode chamar a queda do homem." a) — Quando o Espírito goza do livre-arbítrio, a escolha da existência corporal dependerá sempre exclusivamente de sua vontade, ou essa existência lhe pode ser imposta, como expiação, pela vontade de Deus? "Deus sabe esperar, não apressa a expiação. Todavia, pode impor certa existência a um Espírito, quando este, pela sua inferioridade ou má vontade, não se mostra apto a compreender o que lhe seria mais útil, e quando vê que tal existência servirá para a purificação e o progresso do Espírito, ao mesmo tempo em que lhe sirva de expiação.', 'rascunho'),
  (263, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'O Espírito faz a sua escolha logo depois da morte?', 'Não, muitos acreditam na eternidade das penas, o que, como já se vos disse, é um castigo.', 'rascunho'),
  (264, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Que é o que dirige o Espírito na escolha das provas que queira sofrer?', 'Ele escolhe, de acordo com a natureza de suas faltas, as que o levem à expiação destas e a progredir mais depressa. Uns, portanto, impõem a si mesmos uma vida de misérias e privações, objetivando suportá-las com coragem; outros preferem experimentar as tentações da riqueza e do poder, muito mais perigosas, pelos abusos e má aplicação a que podem dar lugar, pelas paixões inferiores que uma e outros desenvolvem; muitos, finalmente, se decidem a experimentar suas forças nas lutas que terão de sustentar em contacto com o vício.', 'rascunho'),
  (265, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Havendo Espíritos que, por provação, escolhem o contacto do vício, outros não haverá que o busquem por simpatia e pelo desejo de viverem num meio conforme aos seus gostos, ou para poderem entregar-se materialmente a seus pendores materiais?', 'Há, sem dúvida, mas tão-somente entre aqueles cujo senso moral ainda está pouco desenvolvido. A prova vem por si mesma e eles a sofrem mais demoradamente. Cedo ou tarde, compreendem que a satisfação de suas paixões brutais lhes acarretou deploráveis conseqüências, que eles sofrerão durante um tempo que lhes parecerá eterno. E Deus os deixará nessa persuasão, até que se tornem conscientes da falta em que incorreram e peçam, por impulso próprio, lhes seja concedido resgatá-la, mediante úteis provações.', 'rascunho'),
  (266, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Não parece natural que se escolham as provas menos dolorosas?', 'Pode parecer-vos a vós; ao Espírito, não. Logo que este se desliga da matéria, cessa toda ilusão e outra passa a ser a sua maneira de pensar." Sob a influência das idéias carnais, o homem, na Terra, só vê das provas o lado penoso. Tal a razão de lhe parecer natural sejam escolhidas as que, do seu ponto de vista, podem coexistir com os gozos materiais. Na vida espiritual, porém, compara esses gozos fugazes e grosseiros com a inalterável felicidade que lhe é dado entrever e desde logo nenhuma impressão mais lhe causam os passageiros sofrimentos terrenos. Assim, pois, o Espírito pode escolher prova muito rude e, conseguintemente, uma angustiada existência, na esperança de alcançar depressa um estado melhor, como o doente escolhe muitas vezes o remédio mais desagradável para se curar de pronto. Aquele que intenta ligar seu nome à descoberta de um país desconhecido não procura trilhar estrada florida. Conhece os perigos a que se arrisca, mas também sabe que o espera a glória, se lograr bom êxito. A doutrina da liberdade que temos de escolher as nossas existências e as provas que devamos sofrer deixa de parecer singular, desde que se atenda a que os Espíritos, uma vez desprendidos da matéria, apreciam as coisas de modo diverso da nossa maneira de apreciá-los. Divisam a meta, que bem diferente é para eles dos gozos fugitivos do mundo. Após cada existência, vêem o passo que deram e compreendem o que ainda lhes falta em pureza para atingirem aquela meta. Daí o se submeterem voluntariamente a todas as vicissitudes da vida corpórea, solicitando as que possam fazer que a alcancem mais presto. Não há, pois, motivo de espanto no fato de o Espírito não preferir a existência mais suave. Não lhe é possível, no estado de imperfeição em que se encontra, gozar de uma vida isenta de amarguras. Ele o percebe e, precisamente para chegar a fruí-la, é que trata de se melhorar. Não vemos, aliás, todos os dias, exemplos de escolhas tais? Que faz o homem que passa uma parte de sua vida a trabalhar sem trégua, nem descanso, para reunir haveres que lhe assegurem o bem-estar, senão desempenhar uma tarefa que a si mesmo se impôs, tendo em vista melhor futuro? O militar que se oferece para uma perigosa missão, o navegante que afronta não menores perigos, por amor da Ciência ou no seu próprio interesse, que fazem, também eles, senão sujeitar-se a provas voluntárias, de que lhes advirão honras e proveito, se não sucumbirem? A que se não submete ou expõe o homem pelo seu interesse ou pela sua glória? E os concursos não são também todos provas voluntárias a que os concorrentes se sujeitam, com o fito de avançarem na carreira que escolheram? Ninguém galga qualquer posição nas ciências, nas artes, na indústria, senão passando pela série das posições inferiores, que são outras tantas provas. A vida humana é, pois, cópia da vida espiritual; nela se nos deparam em ponto pequeno todas as peripécias da outra. Ora, se na vida terrena muitas vezes escolhemos duras provas, visando posição mais elevada, por que não haveria o Espírito, que enxerga mais longe que o corpo e para quem a vida corporal é apenas incidente de curta duração, de escolher uma existência árdua e laboriosa, desde que o conduza à felicidade eterna? Os que dizem que pedirão para ser príncipes ou milionários, uma vez que ao homem é que caiba escolher a sua existência, se assemelham aos míopes, que apenas vêem aquilo em que tocam, ou a meninos gulosos, que, a quem os interroga sobre isso, respondem que desejam ser pasteleiros ou doceiros. O viajante que atravessa profundo vale ensombrado por espesso nevoeiro não logra apanhar com a vista a extensão da estrada por onde vai, nem os seus pontos extremos. 124 – Allan Kar dec Chegando, porém, ao cume da montanha, abrange com o olhar quanto percorreu do caminho e quanto lhe resta dele a percorrer. Divisa-lhe o termo, vê os obstáculos que ainda terá de transpor e combina então os meios mais seguros de atingi-lo. O Espírito encarnado é qual viajante no sopé da montanha. Desenleado dos liames terrenais, sua visão tudo domina, como a daquele que subiu à crista da serrania. Para o viajor, no termo da sua jornada está o repouso após a fadiga; para o Espírito, está a felicidade suprema, após as tribulações e as provas. Dizem todos os Espíritos que, na erraticidade, eles se aplicam a pesquisar, estudar, observar, a fim de fazerem a sua escolha. Na vida corporal não se nos oferece um exemplo deste fato? Não levamos, freqüentemente, anos a procurar a carreira pela qual afinal nos decidimos, certos de ser a mais apropriada a nos facilitar o caminho da vida? Se numa o nosso intento se malogra, recorremos a outra. Cada uma das que abraçamos representa uma fase, um período da vida. Não nos ocupamos cada dia em cogitar do que faremos no dia seguinte? Ora, que são, para o Espírito, as diversas existências corporais, senão fases, períodos, dias da sua vida espírita, que é, como sabemos, a vida normal, visto que a outra é transitória, passageira?', 'rascunho'),
  (267, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Pode o Espírito proceder à escolha de suas provas, enquanto encarnado?', 'O desejo que então alimenta pode influir na escolha que venha a fazer, dependendo isso da intenção que o anime. Dá-se, porém, que, como Espírito livre, quase sempre vê as coisas de modo diferente. O Espírito por si só é quem faz a escolha; entretanto, ainda uma vez o dizemos, possível lhe é fazê-la, mesmo na vida material, por isso que há sempre momentos em que o Espírito se torna independente da matéria que lhe serve de habitação." a) — Não é decerto como expiação, ou como prova, que muita gente deseja as grandezas e as riquezas. Será? "Indubitavelmente, não. A matéria deseja essa grandeza para gozá-la e o Espírito para conhecer-lhe as vicissitudes.', 'rascunho'),
  (268, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Até que chegue ao estado de pureza perfeita, tem o Espírito que passar constantemente por provas?', 'Sim, mas que não são como o entendeis, pois que só considerais provas as tribulações materiais. Ora, havendo-se elevado a um certo grau, o Espírito, embora não seja ainda perfeito, já não tem que sofrer provas. Continua, porém, sujeito a deveres nada penosos, cuja satisfação lhe auxilia o aperfeiçoamento, mesmo que consistam apenas em auxiliar os outros a se aperfeiçoarem.', 'rascunho'),
  (269, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Pode o Espírito enganar-se quanto à eficiência da prova que escolheu?', 'Pode escolher uma que esteja acima de suas forças e sucumbir. Pode também escolher alguma que nada lhe aproveite, como sucederá se buscar vida ociosa e inútil. Mas, então, voltando ao mundo dos Espíritos, verifica que nada ganhou e pede outra que lhe faculte recuperar o tempo perdido.', 'rascunho'),
  (270, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'A que se devem atribuir as vocações de certas pessoas e a vontade que sentem de seguir uma carreira de preferência a outra?', 'Parece-me que vós mesmos podeis responder a esta pergunta. Pois não é isso a conseqüência de tudo o que acabamos de dizer sobre a escolha das provas e sobre o progresso efetuado em existência anterior?', 'rascunho'),
  (271, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Estudando, na erraticidade, as diversas condições em que poderá progredir, como pensa o Espírito consegui-lo, nascendo, por exemplo, entre canibais?', 'Entre canibais não nascem Espíritos já adiantados, mas Espíritos da natureza dos canibais, ou ainda inferiores aos destes." Sabemos que os nossos antropófagos não se acham no último degrau da escala espiritual e que mundos há onde a bruteza e a ferocidade não têm analogia na Terra. Os Espíritos que aí encarnam são, portanto, inferiores aos mais ínfimos que no nosso mundo encarnam. Para eles, pois, nascer entre os nossos selvagens representa um progresso, como progresso seria, para os antropófagos terrenos, exercerem entre nós uma profissão que os obrigasse a fazer correr sangue. Não podem pôr mais alto suas vistas, porque sua inferioridade moral não lhes permite compreender maior progresso. O Espírito só gradativamente avança. Não lhe é dado transpor de um salto a distância que da civilização separa a barbárie e é esta uma das razões que nos mostram ser necessária a reencarnação, que verdadeiramente corresponde à justiça de Deus. De outro modo, que seria desses milhões de criaturas que todos os dias morrem na maior degradação, se não tivessem meios de alcançar a superioridade? Por que os privaria Deus dos favores concedidos aos outros homens?', 'rascunho'),
  (272, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Poderá dar-se que Espíritos vindos de um mundo inferior à Terra, ou de um povo muito atrasado, como os canibais, por exemplo, nasçam no seio de povos civilizados?', 'Pode. Alguns há que se extraviam, por quererem subir muito alto. Mas, nesse caso, ficam deslocados no meio em que nasceram, por estarem seus costumes e instintos em conflito com os dos outros homens." Tais seres nos oferecem o triste espetáculo da ferocidade dentro da civilização. Voltando para o meio dos canibais, não sofrem uma degradação; apenas volvem ao lugar que lhes é próprio e com isso talvez até ganhem.', 'rascunho'),
  (273, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Será possível que um homem de raça civilizada reencarne, por expiação, numa raça de selvagens?', 'É; mas depende do gênero da expiação. Um senhor, que tenha sido de grande crueldade para os seus escravos, poderá, por sua vez, tornar-se escravo e sofrer os maus-tratos que infligiu a seus semelhantes. Um, que em certa época exerceu o mando, pode, em nova existência, ter que obedecer aos que se curvaram ante a sua vontade. Ser-lhe-á isso uma expiação, que Deus lhe imponha, se ele abusou do seu poder. Também um bom Espírito pode querer encarnar no seio daquelas raças, ocupando posição influente, para fazê-las progredir. Em tal caso, desempenha uma missão." 126 – Allan Kar dec', 'rascunho'),
  (274, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Da existência de diferentes ordens de Espíritos, resulta para estes alguma hierarquia de poderes? Há entre eles subordinação e autoridade?', 'Muito grande. Os Espíritos têm uns sobre os outros a autoridade correspondente ao grau de superioridade que hajam alcançado, autoridade que eles exercem por um ascendente moral irresistível." a) — Podem os Espíritos inferiores subtrair-se à autoridade dos que lhes são superiores? "Eu disse: irresistível.', 'rascunho'),
  (275, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'O poder e a consideração de que um homem gozou na Terra lhe dão supremacia no mundo dos Espíritos?', 'Não; pois que os pequenos serão elevados e os grandes rebaixados. Lê os salmos." a) — Como devemos entender essa elevação e esse rebaixamento? "Não sabes que os Espíritos são de diferentes ordens, conforme seus méritos? Pois bem! O maior da Terra pode pertencer à última categoria entre os Espíritos, ao passo que o seu servo pode estar na primeira. Compreendes isto? Não disse Jesus: aquele que se humilhar será exalçado e aquele que se exalçar será humilhado?', 'rascunho'),
  (276, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Aquele que foi grande na Terra e que, como Espírito, vem a achar-se entre os de ordem inferior, experimenta com isso alguma humilhação?', 'Às vezes bem grande, mormente se era orgulhoso e invejoso.', 'rascunho'),
  (277, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'O soldado que depois da batalha se encontra com o seu general, no mundo dos Espíritos, ainda o tem por seu superior?', 'O título nada vale, a superioridade real é que tem valor.', 'rascunho'),
  (278, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Os Espíritos das diferentes ordens se acham misturados uns com os outros?', 'Sim e não. Quer dizer: eles se vêem, mas se distinguem uns dos outros. Evitam-se ou se aproximam, conforme à simpatia ou à antipatia que reciprocamente uns inspiram aos outros, tal qual sucede entre vós. Constituem um mundo do qual o vosso é pálido reflexo. Os da mesma categoria se reúnem por uma espécie de afinidade e formam grupos ou famílias, unidos pelos laços da simpatia e pelos fins a que visam: os bons, pelo desejo de fazerem o bem; os maus, pelo de fazerem o mal, pela vergonha de suas faltas e pela necessidade de se acharem entre os que se lhes assemelham." Tal uma grande cidade onde os homens de todas as classes e de todas as condições se vêem e encontram, sem se confundirem; onde as sociedades se formam pela analogia dos gostos; onde a virtude e o vício se acotovelam, sem trocarem palavra.', 'rascunho'),
  (279, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Todos os Espíritos têm reciprocamente acesso aos diferentes grupos ou sociedades que eles formam?', 'Os bons vão a toda parte e assim deve ser, para que possam influir sobre os maus. As regiões, porém, que os bons habitam estão interditadas aos Espíritos imperfeitos, a fim de que não as perturbem com suas paixões inferiores.', 'rascunho'),
  (280, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'De que natureza são as relações entre os bons e os maus Espíritos?', 'Os bons se ocupam em combater as más inclinações dos outros, a fim de ajudá-los a subir. É sua missão.', 'rascunho'),
  (281, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Por que os Espíritos inferiores se comprazem em nos induzir ao mal?', 'Pelo despeito que lhes causa o não terem merecido estar entre os bons. O desejo que neles predomina é o de impedirem, quanto possam, que os Espíritos ainda inexperientes alcancem o supremo bem. Querem que os outros experimentem o que eles próprios experimentam. Isto não se dá também entre vós outros?', 'rascunho'),
  (282, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Como se comunicam entre si os Espíritos?', 'Eles se vêem e se compreendem. A palavra é material: é o reflexo do Espírito. O fluido universal estabelece entre eles constante comunicação; é o veiculo da transmissão de seus pensamentos, como, para vós, o ar o é do som. É uma espécie de telégrafo universal, que liga todos os mundos e permite que os Espíritos se correspondam de um mundo a outro.', 'rascunho'),
  (283, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Podem os Espíritos, reciprocamente, dissimular seus pensamentos? Podem ocultar-se uns dos outros?', 'Não; para os Espíritos, tudo é patente, sobretudo para os perfeitos. Podem afastar-se uns dos outros, mas sempre se vêem. Isto, porém, não constitui regra absoluta, porquanto certos Espíritos podem muito bem tornar-se invisíveis a outros Espíritos, se julgarem útil fazê-lo.', 'rascunho'),
  (284, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Como podem os Espíritos, não tendo corpo, comprovar suas individualidades e distinguir-se dos outros seres espirituais que os rodeiam?', 'Comprovam suas individualidades pelo perispírito, que os torna distinguíveis uns dos outros, como faz o corpo entre os homens.', 'rascunho'),
  (285, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Os Espíritos se reconhecem por terem coabitado a Terra? O filho reconhece o pai, o amigo reconhece o seu amigo?', 'Perfeitamente e, assim, de geração em geração." a) — Como é que os que se conheceram na Terra se reconhecem no mundo dos Espíritos? "Vemos a nossa vida pretérita e lemos nela como em um livro. Vendo a dos nossos amigos e dos nossos inimigos, aí vemos a passagem deles da vida corporal à outra." 128 – Allan Kar dec', 'rascunho'),
  (286, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Deixando seus despojos mortais, a alma vê imediatamente os parentes e amigos que a precederam no mundo dos Espíritos?', 'Imediatamente, ainda aqui, não é o termo próprio. Como já dissemos, é- lhe necessário algum tempo para que ela se reconheça a si mesma e alije o véu material.', 'rascunho'),
  (287, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Como é acolhida a alma no seu regresso ao mundo dos Espíritos?', 'A do justo, como bem-amado irmão, desde muito tempo esperado. A do mau, como um ser desprezível.', 'rascunho'),
  (288, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Que sentimento desperta nos Espíritos impuros a chegada entre eles de outro Espírito mau?', 'Os maus ficam satisfeitos quando vêem seres que se lhes assemelham e privados, também, da infinita ventura, qual na Terra um tratante entre seus iguais.', 'rascunho'),
  (289, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Nossos parentes e amigos costumam vir-nos ao encontro quando deixamos a Terra?', 'Sim, os Espíritos vão ao encontro da alma a quem são afeiçoados. Felicitam-na, como se regressasse de uma viagem, por haver escapado aos perigos da estrada, e ajudam-na a desprender-se dos liames corporais. É uma graça concedida aos bons Espíritos o lhes virem ao encontro os que os amam, ao passo que aquele que se acha maculado permanece em insulamento, ou só tem a rodeá-lo os que lhe são semelhantes. É uma punição.', 'rascunho'),
  (290, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Os parentes e amigos sempre se reúnem depois da morte?', 'Depende isso da elevação deles e do caminho que seguem, procurando progredir. Se um está mais adiantado e caminha mais depressa do que outro, não podem os dois conservar-se juntos. Ver-se-ão de tempos a tempos, mas não estarão reunidos para sempre, senão quando puderem caminhar lado a lado, ou quando se houverem igualado na perfeição. Acresce que a privação de ver os parentes e amigos é, às vezes, uma punição.', 'rascunho'),
  (291, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Além da simpatia geral, oriunda da semelhança que entre eles exista, votam-se os Espíritos recíprocas afeições particulares?', 'Do mesmo modo que os homens, sendo, porém, que mais forte é o laço que prende os Espíritos uns aos outros, quando carentes de corpo material, porque então esse laço não se acha exposto às vicissitudes das paixões.', 'rascunho'),
  (292, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Alimentam ódio entre si os Espíritos?', 'Só entre os Espíritos impuros há ódio e são eles que insuflam nos homens as inimizades e as dissensões.', 'rascunho'),
  (293, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Conservarão ressentimento um do outro, no mundo dos Espíritos, dois seres que foram inimigos na Terra?', 'Não; compreenderão que era estúpido o ódio que se votavam mutuamente e pueril o motivo que o inspirava. Apenas os Espíritos imperfeitos conservam uma espécie de animosidade, enquanto se não purificam. Se foi unicamente um interesse material o que os inimizou, nisso não pensarão mais, por pouco desmaterializados que estejam. Não havendo entre eles antipatia e tendo deixado de existir a causa de suas desavenças, aproximam-se uns dos outros com prazer." Sucede como entre dois colegiais que, chegando à idade da ponderação, reconhecem a puerilidade de suas dissensões infantis e deixam de se malquerer.', 'rascunho'),
  (294, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'A lembrança dos atos maus que dois homens praticaram um contra o outro constitui obstáculo a que entre eles reine simpatia?', 'Essa lembrança os induz a se afastarem um do outro.', 'rascunho'),
  (295, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Que sentimento anima, depois da morte, aqueles a quem fizemos mal neste mundo?', 'Se são bons, eles vos perdoam, segundo o vosso arrependimento. Se maus, é possível que guardem ressentimento do mal que lhes fizestes e vos persigam até, não raro, em outra existência. Deus pode permitir que assim seja, por castigo.', 'rascunho'),
  (296, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'São suscetíveis de alterar-se as afeições individuais dos Espíritos?', 'Não, por não estarem eles sujeitos a enganar-se. Falta-lhes a máscara sob que se escondem os hipócritas. Daí vem que, sendo puros, suas afeições são inalteráveis. Suprema felicidade lhes advém do amor que os une.', 'rascunho'),
  (297, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Continua a existir sempre, no mundo dos Espíritos, a afeição mútua que dois seres se consagraram na Terra?', 'Sem dúvida, desde que originada de verdadeira simpatia. Se, porém, nasceu principalmente de causas de ordem física, desaparece com a causa. As afeições entre os Espíritos são mais sólidas e duráveis do que na Terra, porque não se acham subordinadas aos caprichos dos interesses materiais e do amor-próprio.', 'rascunho'),
  (298, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'As almas que devam unir-se estão, desde suas origens, predestinadas a essa união e cada um de nós tem, nalguma parte do Universo, sua metade, a que fatalmente um dia se reunirá?', 'Não; não há união particular e fatal, de duas almas. A união que há é a de todos os Espíritos, mas em graus diversos, segundo a categoria que ocupam, isto é, segundo a perfeição que tenham adquirido. Quanto mais perfeitos, tanto mais unidos. Da discórdia nascem todos os males dos humanos; da concórdia resulta a completa felicidade.', 'rascunho'),
  (299, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Em que sentido se deve entender a palavra metade, de que alguns Espíritos se servem para designar os Espíritos simpáticos? 130 – Allan Kar dec', 'A expressão é inexata. Se um Espírito fosse a metade de outro, separados os dois, estariam ambos incompletos.', 'rascunho'),
  (300, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Se dois Espíritos perfeitamente simpáticos se reunirem, estarão unidos para todo o sempre, ou poderão separar-se e unir-se a outros Espíritos?', 'Todos os Espíritos estão reciprocamente unidos. Falo dos que atingiram a perfeição. Nas esferas inferiores, desde que um Espírito se eleva, já não simpatiza, como dantes, com os que lhe ficaram abaixo.', 'rascunho'),
  (301, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Dois Espíritos simpáticos são complemento um do outro, ou a simpatia entre eles existente é resultado de identidade perfeita?', 'A simpatia que atrai um Espírito para outro resulta da perfeita concordância de seus pendores e instintos. Se um tivesse que completar o outro, perderia a sua individualidade.', 'rascunho'),
  (302, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'A identidade necessária à existência da simpatia perfeita apenas consiste na analogia dos pensamentos e sentimentos, ou também na uniformidade dos conhecimentos adquiridos?', 'Na igualdade dos graus de elevação.', 'rascunho'),
  (303, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Podem tornar-se de futuro simpáticos, Espíritos que presentemente não o são?', 'Todos o serão. Um Espírito, que hoje está numa esfera inferior, ascenderá, aperfeiçoando-se, à em que se acha tal outro Espírito. E ainda mais depressa se dará o encontro dos dois, se o mais elevado, por suportar mal as provas a que esteja submetido, permanecer estacionário." a) — Podem deixar de ser simpáticos um ao outro dois Espíritos que já o sejam? "Certamente, se um deles for preguiçoso." A teoria das metades eternas encerra uma simples figura, representativa da união de dois Espíritos simpáticos. Trata-se de uma expressão usada até na linguagem vulgar e que se não deve tomar ao pé da letra. Não pertencem decerto a uma ordem elevada os Espíritos que a empregaram. Necessariamente, limitado sendo o campo de suas idéias, exprimiram seus pensamentos com os termos de que se teriam utilizado na vida corporal. Não se deve, pois, aceitar a idéia de que, criados um para o outro, dois Espíritos tenham, fatalmente, que se reunir um dia na eternidade, depois de haverem estado separados por tempo mais ou menos longo.', 'rascunho'),
  (304, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Lembra-se o Espírito da sua existência corporal?', 'Lembra-se, isto é, tendo vivido muitas vezes na Terra, recorda-se do que foi como homem e eu te afirmo que freqüentemente ri, penalizado de si mesmo." Tal qual o homem, que chegou à madureza e que ri das suas loucuras de moço, ou das suas puerilidades na meninice.', 'rascunho'),
  (305, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'A lembrança da existência corporal se apresenta ao Espírito, completa e inopinadamente, após a morte?', 'Não; vem-lhe pouco a pouco, qual imagem que surge gradualmente de uma névoa, à medida que nela fixa ele a sua atenção.', 'rascunho'),
  (306, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'O Espírito se lembra, pormenorizadamente, de todos os acontecimentos de sua vida? Apreende o conjunto deles de um golpe de vista retrospectivo?', 'Lembra-se das coisas, de conformidade com as conseqüências que delas resultaram para o estado em que se encontra como Espírito errante. Bem compreendes, portanto, que muitas circunstâncias haverá de sua vida a que não ligará importância alguma e das quais nem sequer procurará recordar-se." a) — Mas, se o quisesse, poderia lembrar-se delas? "Pode lembrar-se dos mais minuciosos pormenores e incidentes, assim relativos aos fatos, como até aos seus pensamentos. Não o faz, porém, desde que não tenha utilidade." b) — Entrevê o Espírito o objetivo da vida terrestre com relação à vida futura? "Certo que o vê e compreende muito melhor do que em vida do seu corpo. Compreende a necessidade da sua purificação para chegar ao infinito e percebe que em cada existência deixa algumas impurezas.', 'rascunho'),
  (307, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Como é que ao Espírito se lhe desenha na memória a sua vida passada? Será por esforço da própria imaginação, ou como um quadro que se lhe apresenta à vista?', 'De uma e outra formas. São-lhe como que presentes todos os atos de que tenha interesse em lembrar-se. Os outros lhe permanecem mais ou menos vagos na mente, ou esquecidos de todo. Quanto mais desmaterializado estiver, tanto menos importância dará às coisas materiais. Essa a razão por que, muitas vezes, evocas um Espírito que acabou de deixar a Terra e verificas que não se lembra dos nomes das pessoas que lhe eram caras, nem de uma porção de coisas que te parecem importantes. É que tudo isso, pouco lhe importando, logo caiu em esquecimento. Ele só se recorda perfeitamente bem dos fatos principais que concorrem para a sua melhoria.', 'rascunho'),
  (308, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'O Espírito se recorda de todas as existências que precederam a que acaba de ter?', 'Todo o seu passado se lhe desdobra à vista, quais a um viajor os trechos do caminho que percorreu. Mas, como já dissemos, não se recorda, de modo absoluto, de todos os seus atos. Lembra-se destes conformemente à influência que tiveram na criação do seu estado atual. Quanto às primeiras existências, as que se podem considerar como a infância do Espírito, essas se perdem no vago e desaparecem na noite do esquecimento.', 'rascunho'),
  (309, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Como considera o Espírito o corpo de que vem de separar-se? 132 – Allan Kar dec', 'Como veste imprestável, que o embaraçava, sentindo-se feliz por estar livre dela." a) — Que sensação lhe causa o espetáculo do seu corpo em decomposição? "Quase sempre se conserva indiferente a isso, como a uma coisa que em nada o interessa.', 'rascunho'),
  (310, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Ao cabo de algum tempo, reconhecerá o Espírito os ossos ou outros objetos que lhe tenham pertencido?', 'Algumas vezes, dependendo do ponto de vista mais ou menos elevado, donde considere as coisas terrenas.', 'rascunho'),
  (311, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'A veneração que se tenha pelos objetos materiais que pertenceram ao Espírito lhe dá prazer e atrai a sua atenção para esses objetos?', 'É sempre grato ao Espírito que se lembrem dele, e os objetos que lhe pertenceram trazem-no à memória dos que ele no mundo deixou. Mas, o que o atrai é o pensamento destas pessoas e não aqueles objetos.', 'rascunho'),
  (312, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'E a lembrança dos sofrimentos por que passaram na última existência corporal, os Espíritos a conservam?', 'Freqüentemente assim acontece e essa lembrança lhes faz compreender melhor o valor da felicidade de que podem gozar como Espíritos.', 'rascunho'),
  (313, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'O homem, que neste mundo foi feliz, deplora a felicidade que perdeu, deixando a Terra?', 'Só os Espíritos inferiores podem sentir saudades de gozos condizentes com uma natureza impura qual a deles, gozos que lhes acarretam a expiação pelo sofrimento. Para os Espíritos elevados, a felicidade eterna é mil vezes preferível aos prazeres efêmeros da Terra." Exatamente como sucede ao homem que, na idade da madureza, nenhuma importância liga ao que tanto o deliciava na infância.', 'rascunho'),
  (314, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Aquele que deu começo a trabalhos de vulto com um fim útil e, que os vê interrompidos pela morte, lamenta, no outro mundo, tê-los deixado por acabar?', 'Não, porque vê que outros estão destinados a concluí-los. Trata, ao contrário, de influenciar outros Espíritos humanos, para que os ultimem. Seu objetivo, na Terra, era o bem da Humanidade: o mesmo objetivo continua a ter no mundo dos Espíritos.', 'rascunho'),
  (315, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'E o que deixou trabalhos de arte ou de literatura, conserva pelas suas obras o amor que lhes tinha quando vivo?', 'De acordo com a sua elevação, aprecia-as de outro ponto de vista e não é raro condene o que maior admiração lhe causava.', 'rascunho'),
  (316, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'No além, o Espírito se interessa pelos trabalhos que se executam na Terra, pelo progresso das artes e das ciências?', 'Conforme à sua elevação ou à missão que possa ter que desempenhar. Muitas vezes, o que vos parece magnífico bem pouco é para certos Espíritos, que, então, o admiram, como o sábio admira a obra de um estudante. Atentam apenas no que prove a elevação dos encarnados e seus progressos.', 'rascunho'),
  (317, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Após a morte, conservam os Espíritos o amor da pátria?', 'O princípio é sempre o mesmo. Para os Espíritos elevados, a pátria é o Universo. Na Terra, a pátria, para eles, está onde se ache o maior número das pessoas que lhes são simpáticas." As condições dos Espíritos e as maneiras por que vêem as coisas variam ao infinito, de conformidade com os graus de desenvolvimento moral e intelectual em que se achem. Geralmente, os Espíritos de ordem elevada só por breve tempo se aproximam da Terra. Tudo o que aí se faz é tão mesquinho em comparação com as grandezas do infinito, tão pueris são, aos olhos deles, as coisas a que os homens mais importância ligam, que quase nenhum atrativo lhes oferece o nosso mundo, a menos que para aí os leve o propósito de concorrerem para o progresso da Humanidade. Os Espíritos de ordem intermédia são os que mais freqüentemente baixam a este planeta, se bem considerem as coisas de um ponto de vista mais alto do que quando encarnados. Os Espíritos vulgares, esses são os que aí mais se comprazem e constituem a massa da população invisível do globo terráqueo. Conservam quase que as mesmas idéias, os mesmos gostos e as mesmas inclinações que tinham quando revestidos do invólucro corpóreo. Metem-se em nossas reuniões, negócios, divertimentos, nos quais tomam parte mais ou menos ativa, segundo seus caracteres. Não podendo satisfazer às suas paixões, gozam na companhia dos que a elas se entregam e os excitam a cultivá-las. Entre eles, no entanto, muitos há, sérios, que vêem e observam para se instruírem e aperfeiçoarem.', 'rascunho'),
  (318, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'As idéias dos Espíritos se modificam quando na erraticidade?', 'Muito; sofrem grandes modificações, à proporção que o Espírito se desmaterializa. Pode este, algumas vezes, permanecer longo tempo imbuído das idéias que tinha na Terra; mas, pouco a pouco, a influência da matéria diminui e ele vê as coisas com maior clareza. É então que procura os meios de se tornar melhor.', 'rascunho'),
  (319, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Já tendo o Espírito vivido a vida espírita antes da sua encarnação, como se explica o seu espanto ao reingressar no mundo dos Espíritos?', 'Isso só se dá no primeiro momento e é efeito da perturbação que se segue ao despertar do Espírito. Mais tarde, ele se vai inteirando da sua condição, à medida que lhe volta a lembrança do passado e que a impressão da vida terrena se lhe apaga." (Nº 163 e seguintes).', 'rascunho'),
  (320, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Sensibiliza os Espíritos o lembrarem-se deles os que lhes foram caros na Terra?', 'Muito mais do que podeis supor. Se são felizes, esse fato lhes aumenta a felicidade. Se são desgraçados, serve-lhes de lenitivo." 134 – Allan Kar dec', 'rascunho'),
  (321, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'O dia da comemoração dos mortos é, para os Espíritos, mais solene do que os outros dias? Apraz-lhes ir ao encontro dos que vão orar nos cemitérios sobre seus túmulos?', 'Os Espíritos acodem nesse dia ao chamado dos que da Terra lhes dirigem seus pensamentos, como o fazem noutro dia qualquer." a) — Mas o de finados é, para eles, um dia especial de reunião junto de suas sepulturas? "Nesse dia, em maior número se reúnem nas necrópoles, porque então também é maior, em tais lugares, o das pessoas que os chamam pelo pensamento. Porém, cada Espírito vai lá somente pelos seus amigos e não pela multidão dos indiferentes." b) — Sob que forma aí comparecem e como os veríamos, se pudessem tornar-se visíveis? "Sob a que tinham quando encarnados.', 'rascunho'),
  (322, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'E os esquecidos, cujos túmulos ninguém vai visitar, também lá, não obstante, comparecem e sentem algum pesar por verem que nenhum amigo se lembra deles?', 'Que lhes importa a Terra? Só pelo coração nos achamos a ela presos. Desde que aí ninguém mais lhe vota afeição, nada mais prende a esse planeta o Espírito, que tem para si o Universo inteiro.', 'rascunho'),
  (323, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'A visita de uma pessoa a um túmulo causa maior contentamento ao Espírito, cujos despojos corporais aí se encontrem, do que a prece que por ele faça essa pessoa em sua casa?', 'Aquele que visita um túmulo apenas manifesta, por essa forma, que pensa no Espírito ausente. A visita é a representação exterior de um fato íntimo. Já dissemos que a prece é que santifica o ato da rememoração. Nada importa o lugar, desde que é feita com o coração.', 'rascunho'),
  (324, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Os Espíritos das pessoas a quem se erigem estátuas ou monumentos assistem à inauguração de umas e outros e experimentam algum prazer nisso?', 'Muitos comparecem a tais solenidades, quando podem; porém, menos os sensibiliza a homenagem que lhes prestam, do que a lembrança que deles guardam os homens.', 'rascunho'),
  (325, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Qual a origem do desejo que certas pessoas exprimem de ser enterradas antes num lugar do que noutro? Será que preferirão, depois de mortas, vir a tal lugar? E essa importância dada a uma coisa tão material constitui indício de inferioridade do Espírito?', 'Afeição particular do Espírito por determinados lugares; inferioridade moral. Que importa este ou aquele canto da Terra a um Espírito elevado? Não sabe ele que sua alma se reunirá às dos que lhe são caros, embora fiquem separados os seus respectivos ossos?" a) — Deve-se considerar futilidade a reunião dos despojos mortais de todos os membros de uma família? "Não; é um costume piedoso e um testemunho de simpatia que dão os que assim procedem aos que lhes foram entes queridos. Conquanto destituída de importância para os Espíritos, essa reunião é útil aos homens: mais concentradas se tornam suas recordações.', 'rascunho'),
  (326, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'Comovem a alma que volta à vida espiritual as honras que lhe prestem aos despojos mortais?', 'Quando já ascendeu a certo grau de perfeição, o Espírito se acha escoimado de vaidades terrenas e compreende a futilidade de todas essas coisas. Porém, ficai sabendo, há Espíritos que, nos primeiros momentos que se seguem à sua morte material, experimentam grande prazer com as honras que lhes tributam, ou se aborrecem com o pouco caso que façam de seus envoltórios corporais. É que ainda conservam alguns dos preconceitos desse mundo.', 'rascunho'),
  (327, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'O Espírito assiste ao seu enterro?', 'Freqüentemente assiste, mas, algumas vezes, se ainda está perturbado, não percebe o que se passa." a) — Lisonjeia-o a concorrência de muitas pessoas ao seu enterramento? "Mais ou menos, conforme o sentimento que as anima.', 'rascunho'),
  (328, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'O Espírito daquele que acaba de morrer assiste à reunião de seus herdeiros?', 'Quase sempre. Para seu ensinamento e castigo dos culpados, Deus permite que assim aconteça. Nessa ocasião, o Espírito julga do valor dos protestos que lhe faziam. Todos os sentimentos se lhe patenteiam e a decepção que lhe causa a rapacidade dos que entre si partilham os bens por ele deixados o esclarece acerca daqueles sentimentos. Chegará, porém, a vez dos que lhe motivam essa decepção.', 'rascunho'),
  (329, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VI — Da vida espírita', 'O instintivo respeito que, em todos os tempos e entre todos os povos, o homem consagrou e consagra aos mortos é efeito da intuição que tem da vida futura?', 'É a conseqüência natural dessa intuição. Se assim não fosse, nenhuma razão de ser teria esse respeito." 136 – Allan Kar dec', 'rascunho'),
  (330, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Sabem os Espíritos em que época reencarnarão?', 'Pressentem-na, como sucede ao cego que se aproxima do fogo. Sabem que têm de retomar um corpo, como sabeis que tendes de morrer um dia, mas ignoram quando isso se dará." a)— Então, a reencarnação é uma necessidade da vida espírita, como a morte o é da vida corporal? "Certamente; assim é.', 'rascunho'),
  (331, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Todos os Espíritos se preocupam com a sua reencarnação?', 'Muitos há que em tal coisa não pensam, que nem sequer a compreendem. Depende de estarem mais ou menos adiantados. Para alguns, a incerteza em que se acham do futuro que os aguarda constitui punição.', 'rascunho'),
  (332, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Pode o Espírito apressar ou retardar o momento da sua reencarnação?', 'Pode apressá-lo, atraindo-o por um desejo ardente. Pode igualmente distanciá-lo, recuando diante da prova, pois entre os Espíritos também há covardes e indiferentes. Nenhum, porém, assim procede impunemente, visto que sofre por isso, como aquele que recusa o remédio capaz de curá-lo.', 'rascunho'),
  (333, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Se se considerasse bastante feliz, numa condição mediana entre os Espíritos errantes e, conseguintemente, não ambicionasse elevar-se, poderia um Espírito prolongar indefinidamente esse estado?', 'Indefinidamente, não. Cedo ou tarde, o Espírito sente a necessidade de progredir. Todos têm que se elevar; esse o destino de todos.', 'rascunho'),
  (334, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Há predestinação na união da alma com tal ou tal corpo, ou só à última hora é feita a escolha do corpo que ela tomará?', 'O Espírito é sempre, de antemão, designado. Tendo escolhido a prova a que queira submeter-se, pede para encarnar. Ora, Deus, que tudo sabe e vê, já antecipadamente sabia e vira que tal Espírito se uniria a tal corpo.', 'rascunho'),
  (335, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Cabe ao Espírito a escolha do corpo em que encarne, ou somente a do gênero de vida que lhe sirva de prova?', 'Pode também escolher o corpo, porquanto as imperfeições que este apresente ainda serão, para o Espírito, provas que lhe auxiliarão o progresso, se vencer os obstáculos que lhe oponha. Nem sempre, porém, lhe é permitida a escolha do seu invólucro corpóreo; mas, simplesmente, a faculdade de pedir que seja tal ou qual." a) — Poderia o Espírito recusar, à última hora, tomar o corpo por ele escolhido? "Se recusasse, sofreria muito mais do que aquele que não tentasse prova alguma.', 'rascunho'),
  (336, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Poderia dar-se não haver Espírito que aceitasse encarnar numa criança que houvesse de nascer?', 'Deus a isso proveria. Quando uma criança tem que nascer vital, está predestinada sempre a ter uma alma. Nada se cria sem que à criação presida um desígnio.', 'rascunho'),
  (337, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Pode a união do Espírito a determinado corpo ser imposta por Deus?', 'Certo, do mesmo modo que as diferentes provas, mormente quando ainda o Espírito não está apto a proceder a uma escolha com conhecimento de causa. Por expiação, pode o Espírito ser constrangido a se unir ao corpo de determinada criança que, pelo seu nascimento e pela posição que venha a ocupar no mundo, se lhe torne instrumento de castigo.', 'rascunho'),
  (338, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Se acontecesse que muitos Espíritos se apresentassem para tomar determinado corpo destinado a nascer, que é o que decidiria sobre a qual deles pertenceria o corpo?', 'Muitos podem pedi-lo; mas, em tal caso, Deus é quem julga qual o mais capaz de desempenhar a missão a que a criança se destina. Porém, como já eu disse, o Espírito é designado antes que soe o instante em que haja de unir-se ao corpo.', 'rascunho'),
  (339, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'No momento de encarnar, o Espírito sofre perturbação semelhante à que experimenta ao desencarnar?', 'Muito maior e sobretudo mais longa. Pela morte, o Espírito sai da escravidão; pelo nascimento, entra para ela." 138 – Allan Kar dec', 'rascunho'),
  (340, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'É solene para o Espírito o instante da sua encarnação? Pratica ele esse ato considerando-o grande e importante?', 'Procede como o viajante que embarca para uma travessia perigosa e que não sabe se encontrará ou não a morte nas ondas que se decide a afrontar." O viajante que embarca sabe a que perigo se lança, mas não sabe se naufragará. O mesmo se dá com o Espírito: conhece o gênero das provas a que se submete, mas não sabe se sucumbirá. Assim como, para o Espírito, a morte do corpo é uma espécie de renascimento, a reencarnação é uma espécie de morte, ou antes, de exílio, de clausura. Ele deixa o mundo dos Espíritos pelo mundo corporal, como o homem deixa este mundo por aquele. Sabe que reencarnará, como o homem sabe que morrerá. Mas, como este com relação à morte, o Espírito só no instante supremo, quando chegou o momento predestinado, tem consciência de que vai reencarnar. Então, qual do homem em agonia, dele se apodera a perturbação, que se prolonga até que a nova existência se ache positivamente encetada. À aproximação do momento de reencarnar, sente uma espécie de agonia.', 'rascunho'),
  (341, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Na incerteza em que se vê, quanto às eventualidades do seu triunfo nas provas que vai suportar na vida, tem o Espírito uma causa de ansiedade antes da sua encarnação?', 'De ansiedade bem grande, pois que as provas da sua existência o retardarão ou farão avançar, conforme as suporte.', 'rascunho'),
  (342, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'No momento de reencarnar, o Espírito se acha acompanhado de outros Espíritos seus amigos, que vêm assistir à sua partida do mundo incorpóreo, como vêm recebê-lo quando para lá volta?', 'Depende da esfera a que pertença. Se já está nas em que reina a afeição, os Espíritos que lhe querem o acompanham até ao último momento, animam e mesmo lhe seguem, muitas vezes, os passos pela vida em fora.', 'rascunho'),
  (343, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Os que vemos, em sonho, que nos testemunham afeto e que se nos apresentam com desconhecidos semblantes, são alguma vez os Espíritos amigos que nos seguem os passos na vida?', 'Muito freqüentemente são eles que vos vêm visitar, como ides visitar um encarcerado.', 'rascunho'),
  (344, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Em que momento a alma se une ao corpo?', 'A união começa na concepção, mas só é completa por ocasião do nascimento. Desde o instante da concepção, o Espírito designado para habitar certo corpo a este se liga por um laço fluídico, que cada vez mais se vai apertando até ao instante em que a criança vê a luz. O grito, que o recém-nascido solta, anuncia que ela se conta no número dos vivos e dos servos de Deus.', 'rascunho'),
  (345, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'É definitiva a união do Espírito com o corpo desde o momento da concepção? Durante esta primeira fase, poderia o Espírito renunciar a habitar o corpo que lhe está destinado?', 'É definitiva a união, no sentido de que outro Espírito não poderia substituir o que está designado para aquele corpo. Mas, como os laços que ao corpo o prendem são ainda muito fracos, facilmente se rompem e podem romper-se por vontade do Espírito, se este recua diante da prova que escolheu. Em tal caso, porém, a criança não vinga.', 'rascunho'),
  (346, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Que faz o Espírito, se o corpo que ele escolheu morre antes de se verificar o nascimento?', 'Escolhe outro." a) — Qual a utilidade dessas mortes prematuras? "Dão-lhes causa, as mais das vezes, as imperfeições da matéria.', 'rascunho'),
  (347, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Que utilidade encontrará um Espírito na sua encarnação em um corpo que morre poucos dias depois de nascido?', 'O ser não tem então consciência plena da sua existência. Assim, a importância da morte é quase nenhuma. Conforme já dissemos, o que há nesses casos de morte prematura é uma prova para os pais.', 'rascunho'),
  (348, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Sabe o Espírito, previamente, que o corpo de sua escolha não tem probabilidade de viver?', 'Sabe-o algumas vezes; mas, se nessa circunstância reside o motivo da escolha, isso significa que está fugindo à prova.', 'rascunho'),
  (349, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Quando falha por qualquer causa a encarnação de um Espírito, é ela suprida imediatamente por outra existência?', 'Nem sempre o é imediatamente. Faz-se mister dar ao Espírito tempo para proceder a nova escolha, a menos que a reencarnação imediata corresponda a anterior determinação.', 'rascunho'),
  (350, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Uma vez unido ao corpo da criança e quando já lhe não é possível voltar atrás, sucede alguma vez deplorar o Espírito a escolha que fez?', 'Perguntas se, como homem, se queixa da vida que tem? Se desejara que outra fosse ela? Sim. Se se arrepende da escolha que fez? Não, pois não sabe ter sido sua a escolha. Depois de encarnado, não pode o Espírito lastimar uma escolha de que não tem consciência. Pode, entretanto, achar pesada demais a carga e considerá- la superior às suas forças. É quando isso acontece que recorre ao suicídio.', 'rascunho'),
  (351, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'No intervalo que medeia da concepção ao nascimento, goza o Espírito de todas as suas faculdades?', 'Mais ou menos, conforme o ponto, em que se ache, dessa fase, porquanto ainda não está encarnado, mas apenas ligado. A partir do instante da concepção, começa o Espírito a ser tomado de perturbação, que o adverte de que lhe soou o 140 – Allan Kar dec momento de começar nova existência corpórea. Essa perturbação cresce de contínuo até ao nascimento. Nesse intervalo, seu estado é quase idêntico ao de um Espírito encarnado durante o sono. À medida que a hora do nascimento se aproxima, suas idéias se apagam, assim como a lembrança do passado, do qual deixa de ter consciência na condição de homem, logo que entra na vida. Essa lembrança, porém, lhe volta pouco a pouco ao retornar ao estado de Espírito.', 'rascunho'),
  (352, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Imediatamente ao nascer recobra o Espírito a plenitude das suas faculdades?', 'Não, elas se desenvolvem gradualmente com os órgãos. O Espírito se acha numa existência nova; preciso é que aprenda a servir-se dos instrumentos de que dispõe. As idéias lhe voltam pouco a pouco, como a uma pessoa que desperta e se vê em situação diversa da que ocupava na véspera.', 'rascunho'),
  (353, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Não sendo completa a união do Espírito ao corpo, não estando definitivamente consumada, senão depois do nascimento, poder-se-á considerar o feto como dotado de alma?', 'O Espírito que o vai animar existe, de certo modo, fora dele. O feto não tem pois, propriamente falando, uma alma, visto que a encarnação está apenas em via de operar-se. Achasse, entretanto, ligado à alma que virá a possuir.', 'rascunho'),
  (354, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Como se explica a vida intra-uterina?', 'É a da planta que vegeta. A criança vive vida animal. O homem tem a vida vegetal e a vida animal que, pelo seu nascimento, se completam com a vida espiritual.', 'rascunho'),
  (355, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Há, de fato, como o indica a Ciência, crianças que já no seio materno não são vitais? Com que fim ocorre isso?', 'Freqüentemente isso se dá e Deus o permite como prova, quer para os pais do nascituro, quer para o Espírito designado a tomar lugar entre os vivos.', 'rascunho'),
  (356, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Entre os natimortos alguns haverá que não tenham sido destinados à encarnação de Espíritos?', 'Alguns há, efetivamente, a cujos corpos nunca nenhum Espírito esteve destinado. Nada tinha que se efetuar para eles. Tais crianças então só vêm por seus pais." a) — Pode chegar a termo de nascimento um ser dessa natureza? "Algumas vezes; mas não vive." b) — Segue-se daí que toda criança que vive após o nascimento tem forçosamente encarnado em si um Espírito? "Que seria ela, sé assim não acontecesse? Não seria um ser humano.', 'rascunho'),
  (357, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Que conseqüências tem para o Espírito o aborto?', 'É uma existência nulificada e que ele terá de recomeçar.', 'rascunho'),
  (358, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Constitui crime a provocação do aborto, em qualquer período da gestação?', 'Há crime sempre que transgredis a lei de Deus. Uma mãe, ou quem quer que seja, cometerá crime sempre que tirar a vida a uma criança antes do seu nascimento, por isso que impede uma alma de passar pelas provas a que serviria de instrumento o corpo que se estava formando.', 'rascunho'),
  (359, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Dado o caso que o nascimento da criança pusesse em perigo a vida da mãe dela, haverá crime em sacrificar-se a primeira para salvar a segunda?', 'Preferível é se sacrifique o ser que ainda não existe a sacrificar-se o que já existe.', 'rascunho'),
  (360, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Será racional ter-se para com um feto as mesmas atenções que se dispensam ao corpo de uma criança que viveu algum tempo?', 'Vede em tudo isso a vontade e a obra de Deus. Não trateis, pois, desatenciosamente, coisas que deveis respeitar. Por que não respeitar as obras da criação, algumas vezes incompletas por vontade do Criador? Tudo ocorre segundo os seus desígnios e ninguém é chamado para ser seu juiz.', 'rascunho'),
  (361, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Qual a origem das qualidades morais, boas ou más, do homem?', 'São as do Espírito nele encarnado. Quanto mais puro é esse Espírito, tanto mais propenso ao bem é o homem." a) — Seguir-se-á daí que o homem de bem é a encarnação de um bom Espírito e o homem vicioso a de um Espírito mau? "Sim, mas, dize antes que o homem vicioso é a encarnação de um Espírito imperfeito, pois, do contrário, poderias fazer crer na existência de Espíritos sempre maus, a que chamais demônios.', 'rascunho'),
  (362, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Qual o caráter dos indivíduos em que encarnam Espíritos desassisados e levianos?', 'São indivíduos estúrdios, maliciosos e, não raro, criaturas malfazejas.', 'rascunho'),
  (363, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Têm os Espíritos paixões de que não partilhe a Humanidade?', 'Não, que, de outro modo, vo-las teriam comunicado.', 'rascunho'),
  (364, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'O mesmo Espírito dá ao homem as qualidades morais e as da inteligência?', 'Certamente e isso em virtude do grau de adiantamento a que se haja elevado. O homem não tem em si dois Espíritos.', 'rascunho'),
  (365, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Por que é que alguns homens muito inteligentes, o que indica acharem-se encarnados neles Espíritos superiores, são ao mesmo tempo profundamente viciosos?', 'É que não são ainda bastante puros os Espíritos encarnados nesses homens, que, então, e por isso, cedem à influência de outros Espíritos mais 142 – Allan Kar dec imperfeitos. O Espírito progride em insensível marcha ascendente, mas o progresso não se efetua simultaneamente em todos os sentidos. Durante um período da sua existência, ele se adianta em ciência; durante outro, em moralidade.', 'rascunho'),
  (366, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Que se deve pensar da opinião dos que pretendem que as diferentes faculdades intelectuais e morais do homem resultam da encarnação, nele, de outros tantos Espíritos, diferentes entre si, cada um com uma aptidão especial?', 'Refletindo, reconhecereis que é absurda. O Espírito tem que ter todas as aptidões. Para progredir, precisa de uma vontade única. Se o homem fosse um amálgama de Espíritos, essa vontade não existiria e ele careceria de individualidade, pois que, por sua morte, todos aqueles Espíritos formariam um bando de pássaros escapados da gaiola. Queixa-se, amiúde, o homem de não compreender certas coisas e, no entanto, curioso é ver-se como multiplica as dificuldades, quando tem ao seu alcance explicações muito simples e naturais. Ainda neste caso tomam o efeito pela causa. Fazem, com relação à criatura humana, o que, com relação a Deus, faziam os pagãos, que acreditavam em tantos deuses quantos eram os fenômenos no Universo, se bem que as pessoas sensatas, com eles coexistentes, apenas viam em tais fenômenos efeitos provindos de uma causa única – Deus." O mundo físico e o mundo moral nos oferecem, a este respeito, vários pontos de semelhança. Enquanto se detiveram na aparência dos fenômenos, os cientistas acreditaram fosse múltipla a matéria. Hoje, compreende-se ser bem possível que tão variados fenômenos consistam apenas em modificações da matéria elementar única. As diversas faculdades são manifestações de uma mesma causa, que é a alma, ou do Espírito encarnado, e não de muitas almas, exatamente como os diferentes sons do órgão, os quais procedem todos do ar e não de tantas espécies de ar, quantos os sons. De semelhante sistema decorreria que, quando um homem perde ou adquire certas aptidões, certos pendores, isso significaria que outros tantos Espíritos teriam vindo habitá-lo ou o teriam deixado, o que o tornaria um ser múltiplo, sem individualidade e, conseguintemente, sem responsabilidade. Acresce que o contradizem numerosíssimos exemplos de manifestações de Espíritos, em que estes provam suas personalidades e identidade.', 'rascunho'),
  (367, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Unindo-se ao corpo, o Espírito se identifica com a matéria?', 'A matéria é apenas o envoltório do Espírito, como o vestuário o é do corpo. Unindo-se a este, o Espírito conserva os atributos da natureza espiritual.', 'rascunho'),
  (368, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Após sua união com o corpo, exerce o Espírito, com liberdade plena, suas faculdades?', 'O exercício das faculdades depende dos órgãos que lhes servem de instrumento. A grosseria da matéria as enfraquece." a) — Assim, o invólucro material é obstáculo à livre manifestação das faculdades do Espírito, como um vidro opaco o é à livre irradiação da luz? "É, como vidro muito opaco." Pode-se comparar a ação que a matéria grosseira exerce sobre o Espírito à de um charco lodoso sobre um corpo nele mergulhado, ao qual tira a liberdade dos movimentos.', 'rascunho'),
  (369, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'O livre exercício das faculdades da alma está subordinado ao desenvolvimento dos órgãos?', 'Os órgãos são os instrumentos da manifestação das faculdades da alma, manifestação que se acha subordinada ao desenvolvimento e ao grau de perfeição dos órgãos, como a excelência de um trabalho o está à da ferramenta própria à sua execução.', 'rascunho'),
  (370, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Da influência dos órgãos se pode inferir a existência de uma relação entre o desenvolvimento dos do cérebro e o das faculdades morais e intelectuais?', 'Não confundais o efeito com a causa. O Espírito dispõe sempre das faculdades que lhe são próprias. Ora, não são os órgãos que dão as faculdades, e sim estas que impulsionam o desenvolvimento dos órgãos." a) — Dever-se-á deduzir daí que a diversidade das aptidões entre os homens deriva unicamente do estado do Espírito? "O termo — unicamente — não exprime com toda a exatidão o que ocorre. O princípio dessa diversidade reside nas qualidades do Espírito, que pode ser mais ou menos adiantado. Cumpre, porém, se leve em conta a influência da matéria, que mais ou menos lhe cerceia o exercício de suas faculdades." Encarnando, traz o Espírito certas predisposições e, se se admitir que a cada uma corresponda no cérebro um órgão, o desenvolvimento desses órgãos será efeito e não causa. Se nos órgãos estivesse o princípio das faculdades, o homem seria máquina sem livre-arbítrio e sem a responsabilidade de seus atos. Forçoso então fora admitir-se que os maiores gênios, os sábios, os poetas, os artistas, só o são porque o acaso lhes deu órgãos especiais, donde se seguiria que, sem esses órgãos, não teriam sido gênios e que, assim, o maior dos imbecis houvera podido ser um Newton, um Vergílio, ou um Rafael, desde que de certos órgãos se achassem providos. Ainda mais absurda se mostra semelhante hipótese, se a aplicarmos às qualidades morais. Efetivamente, segundo esse sistema, um Vicente de Paulo, se a Natureza o dotara de tal ou tal órgão, teria podido ser um celerado e o maior dos celerados não precisaria senão de um certo órgão para ser um Vicente de Paulo. Admita-se, ao contrário, que os órgãos especiais, dado existam, são conseqüentes, que se desenvolvem por efeito do exercício da faculdade, como os músculos por efeito do movimento, e a nenhuma conclusão irracional se chegará. Sirvamo-nos de uma comparação, trivial à força de ser verdadeira. Por alguns sinais fisionômicos se reconhece que um homem tem o vício da embriaguez. Serão esses sinais que fazem dele um ébrio, ou será a ebriedade que nele imprime aqueles sinais? Pode dizer-se que os órgãos recebem o cunho das faculdades.', 'rascunho'),
  (371, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Tem algum fundamento o pretender-se que a alma dos cretinos e dos idiotas é de natureza inferior?', 'Nenhum. Eles trazem almas humanas, não raro mais inteligentes do que supondes, mas que sofrem da insuficiência dos meios de que dispõem para se comunicar, da mesma forma que o mudo sofre da impossibilidade de falar." 144 – Allan Kar dec', 'rascunho'),
  (372, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Que objetivo visa a Providência criando seres desgraçados, como os cretinos e os idiotas?', 'Os que habitam corpos de idiotas são Espíritos sujeitos a uma punição. Sofrem por efeito do constrangimento que experimentam e da impossibilidade em que estão de se manifestarem mediante órgãos não desenvolvidos ou desmantelados." a) — Não há, pois, fundamento para dizer-se que os órgãos nada influem sobre as faculdades? "Nunca dissemos que os órgãos não têm influência. Têm-na muito grande sobre a manifestação das faculdades, mas não são eles a origem destas. Aqui está a diferença. Um músico excelente, com um instrumento defeituoso, não dará a ouvir boa música, o que não fará que deixe de ser bom músico." Importa se distinga o estado normal do estado patológico. No primeiro, o moral vence os obstáculos que a matéria lhe opõe. Há, porém, casos em que a matéria oferece tal resistência que as manifestações anímicas ficam obstadas ou desnaturadas, como nos de idiotismo e de loucura. São casos patológicos e, não gozando nesse estado a alma de toda a sua liberdade, a própria lei humana a isenta da responsabilidade de seus atos.', 'rascunho'),
  (373, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Qual será o mérito da existência de seres que, como os cretinos e os idiotas, não podendo fazer o bem nem o mal, se acham incapacitados de progredir?', 'É uma expiação decorrente do abuso que fizeram de certas faculdades. É um estacionamento temporário." a) — Pode assim o corpo de um idiota conter um Espírito que tenha animado um homem de gênio em precedente existência? "Certo. O gênio se torna por vezes um flagelo, quando dele abusa o homem." A superioridade moral nem sempre guarda proporção com a superioridade intelectual e os grandes gênios podem ter muito que expiar. Daí, freqüentemente, lhes resulta uma existência inferior à que tiveram e uma causa de sofrimentos. Os embaraços que o Espírito encontra para suas manifestações se lhe assemelham às algemas que tolhem os movimentos a um homem vigoroso. Pode dizer-se que os cretinos e os idiotas são estropiados do cérebro, como o coxo o é das pernas e dos olhos o cego.', 'rascunho'),
  (374, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Na condição de Espírito livre, tem o idiota consciência do seu estado mental?', 'Freqüentemente tem. Compreende que as cadeias que lhe obstam ao vôo são prova e expiação.', 'rascunho'),
  (375, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Qual, na loucura, a situação do Espírito?', 'O Espírito, quando em liberdade, recebe diretamente suas impressões e diretamente exerce sua ação sobre a matéria. Encarnado, porém, ele se encontra em condições muito diversas e na contingência de só o fazer com o auxílio de órgãos especiais. Altere-se uma parte ou o conjunto de tais órgãos e eis que se lhe interrompem, no que destes dependam, a ação ou as impressões. Se perde os olhos, fica cego; se o ouvido, torna-se surdo, etc. Imagina agora que seja o órgão, que preside às manifestações da inteligência, o atacado ou modificado, parcial ou inteiramente, e fácil te será compreender que, só tendo o Espírito a seu serviço órgãos incompletos ou alterados, uma perturbação resultará de que ele, por si mesmo e no seu foro íntimo, tem perfeita consciência, mas cujo curso não lhe está nas mãos deter." a) — Então, o desorganizado é sempre o corpo e não o Espírito? "Exatamente; mas, convém não perder de vista que, assim como o Espírito atua sobre a matéria, também esta reage sobre ele, dentro de certos limites, e que pode acontecer impressionar-se o Espírito temporariamente com a alteração dos órgãos pelos quais se manifesta e recebe as impressões. Pode mesmo suceder que, com a continuação, durando longo tempo a loucura, a repetição dos mesmos atos acabe por exercer sobre o Espírito uma influência, de que ele não se libertará senão depois de se haver libertado de toda impressão material.', 'rascunho'),
  (376, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Por que razão a loucura leva o homem algumas vezes ao suicídio?', 'O Espírito sofre pelo constrangimento em que se acha e pela impossibilidade em que se vê de manifestar-se livremente, donde o procurar na morte um meio de quebrar seus grilhões.', 'rascunho'),
  (377, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Depois da morte, o Espírito do alienado se ressente do desarranjo de suas faculdades?', 'Pode ressentir-se, durante algum tempo após a morte, até que se desligue completamente da matéria, como o homem que desperta se ressente, por algum tempo, da perturbação em que o lançara o sono.', 'rascunho'),
  (378, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'De que modo a alteração do cérebro reage sobre o Espírito depois da morte?', 'Como uma recordação. Um peso oprime o Espírito e, como ele não teve a compreensão de tudo o que se passou durante a sua loucura, sempre se faz mister um certo tempo, a fim de se pôr ao corrente de tudo. Por isso é que, quanto mais durar a loucura no curso da vida terrena, tanto mais lhe durará a incerteza, o constrangimento, depois da morte. Liberto do corpo, o Espírito se ressente, por certo tempo, da impressão dos laços que àquele o prendiam.', 'rascunho'),
  (379, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'É tão desenvolvido, quanto o de um adulto, o Espírito que anima o corpo de uma criança?', 'Pode até ser mais, se mais progrediu. Apenas a imperfeição dos órgãos infantis o impede de se manifestar. Obra de conformidade com o instrumento de que dispõe.', 'rascunho'),
  (380, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Abstraindo do obstáculo que a imperfeição dos órgãos opõe à sua livre manifestação, o Espírito, numa criancinha, pensa como criança ou como adulto?', 'Desde que se trate de uma criança, é claro que, não estando ainda nela desenvolvidos, não podem os órgãos da inteligência dar toda a intuição própria de 146 – Allan Kar dec um adulto ao Espírito que a anima. Este, pois, tem, efetivamente, limitada a inteligência, enquanto a idade lhe não amadurece a razão. A perturbação que o ato da encarnação produz no Espírito não cessa de súbito, por ocasião do nascimento. Só gradualmente se dissipa, com o desenvolvimento dos órgãos." Há um fato de observação, que apóia esta resposta. Os sonhos, numa criança, não apresentam o caráter dos de um adulto. Quase sempre pueril é o objeto dos sonhos infantis, o que indica de que natureza são a s preocupações do respectivo Espírito.', 'rascunho'),
  (381, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Por morte da criança, readquire o Espírito, imediatamente, o seu precedente vigor?', 'Assim tem que ser, pois que se vê desembaraçado de seu invólucro corporal. Entretanto, não readquire a anterior lucidez, senão quando se tenha completamente separado daquele envoltório, isto é, quando mais nenhum laço exista entre ele e o corpo.', 'rascunho'),
  (382, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Durante a infância sofre o Espírito encarnado, em conseqüência do constrangimento que a imperfeição dos órgãos lhe impõe?', 'Não. Esse estado corresponde a uma necessidade, está na ordem da natureza e de acordo com as vistas da Providência. É um período de repouso do Espírito.', 'rascunho'),
  (383, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Qual, para este, a utilidade de passar pelo estado de infância?', 'Encarnando, com o objetivo de se aperfeiçoar, o Espírito, durante esse período, é mais acessível às impressões que recebe, capazes de lhe auxiliarem o adiantamento, para o que devem contribuir os incumbidos de educá-lo.', 'rascunho'),
  (384, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Por que é o choro a primeira manifestação da criança ao nascer?', 'Para estimular o interesse da genitora e provocar os cuidados de que há mister. Não é evidente que se suas manifestações fossem todas de alegria, quando ainda não sabe falar, pouco se inquietariam os que o cercam com os cuidados que lhe são indispensáveis? Admirai, pois, em tudo a sabedoria da Providência.', 'rascunho'),
  (385, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Que é o que motiva a mudança que se opera no caráter do indivíduo em certa idade, especialmente ao sair da adolescência? É que o Espírito se modifica?', 'É que o Espírito retoma a natureza que lhe é própria e se mostra qual era. Não conheceis o que a inocência das crianças oculta. Não sabeis o que elas são, nem o que o foram, nem o que serão. Contudo, afeição lhes tendes, as acariciais, como se fossem parcelas de vós mesmos, a tal ponto que se considera o amor que uma mãe consagra a seus filhos como o maior amor que um ser possa votar a outro. Donde nasce o meigo afeto, a terna benevolência que mesmo os estranhos sentem por uma criança? Sabeis? Não. Pois bem! Vou explicá-lo." "As crianças são os seres que Deus manda a novas existências. Para que não lhe possam imputar excessiva severidade, dá-lhes ele todos os aspectos da inocência. Ainda quando se trata de uma criança de maus pendores, cobrem-se-lhe as más ações com a capa da inconsciência. Essa inocência não constitui superioridade real com relação ao que eram antes, não. É a imagem do que deveriam ser e, se não o são, o conseqüente castigo exclusivamente sobre elas recai." "Não foi, todavia, por elas somente que Deus lhes deu esse aspecto de inocência; foi também e sobretudo por seus pais, de cujo amor necessita a fraqueza que as caracteriza. Ora, esse amor se enfraqueceria grandemente à vista de um caráter áspero e intratável, ao passo que, julgando seus filhos bons e dóceis, os pais lhes dedicam toda a afeição e os cercam dos mais minuciosos cuidados. Desde que, porém, os filhos não mais precisam da proteção e assistência que lhes foram dispensadas durante quinze ou vinte anos, surge-lhes o caráter real e individual em toda a nudez. Conservam-se bons, se eram fundamentalmente bons; mas, sempre irisados de matizes que a primeira infância manteve ocultos. Como vedes, os processos de Deus são sempre os melhores e, quando se tem o coração puro, facilmente se lhes apreende a explicação." "Com efeito, ponderai que nos vossos lares possivelmente nascem crianças cujos Espíritos vêm de mundos onde contraíram hábitos diferentes dos vossos e dizei-me como poderiam estar no vosso meio esses seres, trazendo paixões diversas das que nutris, inclinações, gostos, inteiramente opostos aos vossos; como poderiam enfileirar-se entre vós, senão como Deus o determinou, isto é, passando pelo tamis da infância? Nesta se vêm confundir todas as idéias, todos os caracteres, todas as variedades de seres gerados pela infinidade dos mundos em que medram as criaturas. E vós mesmos, ao morrerdes, vos achareis num estado que é uma espécie de infância, entre novos irmãos. Ao volverdes à existência extraterrena, ignorareis os hábitos, os costumes, as relações que se observam nesse mundo, para vós, novo. Manejareis com dificuldade uma linguagem que não estais acostumado a falar, linguagem mais vivaz do que o é agora o vosso pensamento. " "A infância ainda tem outra utilidade. Os Espíritos só entram na vida corporal para se aperfeiçoarem, para se melhorarem. A delicadeza da idade infantil os torna brandos, acessíveis aos conselhos da experiência e dos que devam fazê-los progredir. Nessa fase é que se lhes pode reformar os caracteres e reprimir os maus pendores. Tal o dever que Deus impôs aos pais, missão sagrada de que terão de dar contas." "Assim, portanto, a infância é não só útil, necessária, indispensável, mas também conseqüência natural das leis que Deus estabeleceu e que regem o Universo.', 'rascunho'),
  (386, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Podem dois seres, que se conheceram e estimaram, encontrar-se noutra existência corporal e reconhecer-se?', 'Reconhecer-se, não. Podem, porém, sentir-se atraídos um para o outro. E, freqüentemente, diversa não é a causa de íntimas ligações fundadas em sincera afeição. Um do outro dois seres se aproximam devido a circunstâncias aparentemente fortuitas, mas que na realidade resultam da atração de dois Espíritos, que se buscam reciprocamente por entre a multidão." a) — Não lhes seria mais agradável reconhecerem-se? 148 – Allan Kar dec "Nem sempre. A recordação das passadas existências teria inconvenientes maiores do que imaginais. Depois de mortos, reconhecer-se-ão e saberão que tempo passaram juntos.', 'rascunho'),
  (387, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'A simpatia tem sempre por princípio um anterior conhecimento?', 'Não. Dois Espíritos, que se ligam bem, naturalmente se procuram um ao outro, sem que se tenham conhecido como homens.', 'rascunho'),
  (388, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Os encontros, que costumam dar-se, de algumas pessoas e que comumente se atribuem ao acaso, não serão efeito de uma certa relação de simpatia?', 'Entre os seres pensantes há ligação que ainda não conheceis. O magnetismo é o piloto desta ciência, que mais tarde compreendereis melhor.', 'rascunho'),
  (389, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'E a repulsão instintiva que se experimenta por algumas pessoas, donde se origina?', 'São Espíritos antipáticos que se adivinham e reconhecem, sem se falarem.', 'rascunho'),
  (390, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'A antipatia instintiva é sempre sinal de natureza má?', 'De não simpatizarem um com o outro, não se segue que dois Espíritos sejam necessariamente maus. A antipatia, entre eles, pode derivar de diversidade no modo de pensar. À proporção, porém, que se forem elevando, essa divergência irá desaparecendo e a antipatia deixará de existir.', 'rascunho'),
  (391, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'A antipatia entre duas pessoas nasce primeiro na que tem pior Espírito, ou na que o tem melhor?', 'Numa e noutra indiferentemente, mas distintas são as causas e os efeitos nas duas. Um Espírito mau antipatiza com quem quer que o possa julgar e desmascarar. Ao ver pela primeira vez uma pessoa, logo sabe que vai ser censurado. Seu afastamento dessa pessoa se transforma em ódio, em inveja e lhe inspira o desejo de praticar o mal. O bom Espírito sente repulsão pelo mau, por saber que este o não compreenderá e porque díspares dos dele são os seus sentimentos. Entretanto, consciente da sua superioridade, não alimenta ódio, nem inveja contra o outro. Limita-se a evitá-lo e a lastimá-lo.', 'rascunho'),
  (392, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Por que perde o Espírito encarnado a lembrança do seu passado?', 'Não pode o homem, nem deve, saber tudo. Deus assim o quer em sua sabedoria. Sem o véu que lhe oculta certas coisas, ficaria ofuscado, como quem, sem transição, saísse do escuro para o claro. Esquecido de seu passado ele é mais senhor de si.', 'rascunho'),
  (393, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Como pode o homem ser responsável por atos e resgatar faltas de que se não lembra? Como pode aproveitar da experiência de vidas de que se esqueceu? Concebe-se que as tribulações da existência lhe servissem de lição, se se recordasse do que as tenha podido ocasionar. Desde que, porém, disso não se recorda, cada existência é, para ele, como se fosse a primeira e eis que então está sempre a recomeçar. Como conciliar isto com a justiça de Deus?', 'Em cada nova existência, o homem dispõe de mais inteligência e melhor pode distinguir o bem do mal. Onde o seu mérito se se lembrasse de todo o passado? Quando o Espírito volta à vida anterior (a vida espírita), diante dos olhos se lhe estende toda a sua vida pretérita. Vê as faltas que cometeu e que deram causa ao seu sofrer, assim como de que modo as teria evitado. Reconhece justa a situação em que se acha e busca então uma existência capaz de reparar a que vem de transcorrer. Escolhe provas análogas às de que não soube aproveitar, ou as lutas que considere apropriadas ao seu adiantamento e pede a Espíritos que lhe são superiores que o ajudem na nova empresa que sobre si toma, ciente de que o Espírito, que lhe for dado por guia nessa outra existência, se esforçará pelo levar a reparar suas faltas, dando-lhe uma espécie de intuição das em que incorreu. Tendes essa intuição no pensamento, no desejo criminoso que freqüentemente vos assalta e a que instintivamente resistis, atribuindo, as mais das vezes, essa resistência aos princípios que recebestes de vossos pais, quando é a voz da consciência que vos fala. Essa voz, que é a lembrança do passado, vos adverte para não recairdes nas faltas de que já vos fizestes culpados. Em a nova existência, se sofre com coragem aquelas provas e resiste, o Espírito se eleva e ascende na hierarquia dos Espíritos, ao voltar para o meio deles." Não temos, é certo, durante a vida corpórea, lembrança exata do que fomos e do que fizemos em anteriores existências; mas temos de tudo isso a intuição, sendo as nossas tendências instintivas uma reminiscência do passado. E a nossa consciência, que é o desejo que experimentamos de não reincidir nas faltas já cometidas, nos concita à resistência àqueles pendores.', 'rascunho'),
  (394, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Nos mundos mais elevados do que a Terra, onde os que os habitam não se vêem premidos pelas necessidades físicas, pelas enfermidades que nos afligem, os homens compreendem que são mais felizes do que nós? Relativa é, em geral, a felicidade. Sentimo-la, mediante comparação com um estado menos ditoso. Visto que, em suma, alguns desses mundos, se bem melhores do que o nosso, ainda não atingiram o estado de perfeição, seus habitantes devem ter motivos de desgostos, embora de gênero diverso dos nossos. Entre nós, o rico, conquanto não sofra as angústias das necessidades materiais, como o pobre, nem por isso se acha isento de tribulações, que lhe tornam amarga a vida. Pergunto então: Na situação em que se encontram, os habitantes desses mundos não se consideram tão infelizes quanto nós, na em que nos vemos, e não se lastimam da sorte, olvidados de existências inferiores que lhes sirvam de termos de comparação?', 'Cabem aqui duas respostas distintas. Há mundos, entre os de que falas, cujos habitantes guardam lembrança clara e exata de suas existências passadas. Esses, compreendes, podem e sabem apreciar a felicidade de que Deus lhes permite fruir. Outros há, porém, cujos habitantes, achando-se, como dizes, em melhores condições do que vós na Terra, não deixam de experimentar grandes desgostos, até desgraças. Esses não apreciam a felicidade de que gozam, pela razão mesma de se 150 – Allan Kar dec não recordarem de um estado mais infeliz. Entretanto, se não a apreciam como homens, apreciam-na como Espíritos." No esquecimento das existências anteriormente transcorridas, sobretudo quando foram amarguradas, não há qualquer coisa de providencial e que revela a sabedoria divina? Nos mundos superiores, quando o recordá-las já não constitui pesadelo, é que as vidas desgraçadas se apresentam à memória. Nos mundos inferiores, a lembrança de todas as que se tenham sofrido não agravaria as infelicidades presentes? Concluamos, pois, daí que tudo o que Deus fez é perfeito e que não nos toca criticar-lhe as obras, nem lhe ensinar como deveria ter regulado o Universo. Gravíssimos inconvenientes teria o nos lembrarmos das nossas individualidades anteriores. Em certos casos, humilhar-nos-ia sobremaneira. Em outros nos exaltaria o orgulho, peando-nos, em conseqüência, o livre-arbítrio. Para nos melhorarmos, dá-nos Deus exatamente o que nos é necessário e basta: a voz da consciência e os pendores instintivos. Priva-nos do que nos prejudicaria. Acrescentemos que, se nos recordássemos dos nossos precedentes atos pessoais, igualmente nos recordaríamos dos dos outros homens, do que resultariam talvez os mais desastrosos efeitos para as relações sociais. Nem sempre podendo honrar-nos do nosso passado, melhor é que sobre ele um véu seja lançado. Isto concorda perfeitamente com a doutrina dos Espíritos acerca dos mundos superiores à Terra. Nesses mundos, onde só reina o bem, a reminiscência do passado nada tem de dolorosa. Tal a razão por que neles as criaturas se lembram da sua antecedente existência, como nos lembramos do que fizemos na véspera. Quanto à estada em mundos inferiores, não passa então, como já dissemos, de mau sonho.', 'rascunho'),
  (395, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Podemos ter algumas revelações a respeito de nossas vidas anteriores?', 'Nem sempre. Contudo, muitos sabem o que foram e o que faziam. Se se lhes permitisse dizê-lo abertamente, extraordinárias revelações fariam sobre o passado.', 'rascunho'),
  (396, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Algumas pessoas julgam ter vaga recordação de um passado desconhecido, que se lhes apresenta como a imagem fugitiva de um sonho, que em vão se tenta reter. Não há nisso simples ilusão?', 'Algumas vezes, é uma impressão real; mas também, freqüentemente, não passa de mera ilusão, contra a qual precisa o homem pôr-se em guarda, porquanto pode ser efeito de superexcitada imaginação.', 'rascunho'),
  (397, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Nas existências corpóreas de natureza mais elevada do que a nossa, é mais clara a lembrança das anteriores?', 'Sim, à medida que o corpo se torna menos material, com mais exatidão o homem se lembra do seu passado. Esta lembrança, os que habitam os mundos de ordem superior a têm mais nítida.', 'rascunho'),
  (398, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Sendo os pendores instintivos uma reminiscência do seu passado, dar-se-á que, pelo estudo desses pendores, seja possível ao homem conhecer as faltas que cometeu?', 'Até certo ponto, assim é. Preciso se torna, porém, levar em conta a melhora que se possa ter operado no Espírito e as resoluções que ele haja tomado na erraticidade. Pode suceder que a existência atual seja muito melhor que a precedente." a) — Poderá também ser pior, isto é, poderá o Espírito cometer, numa existência, faltas que não praticou em a precedente? "Depende do seu adiantamento. Se não souber triunfar das provas, possivelmente será arrastado a novas faltas, conseqüentes, então, da posição que escolheu. Mas, em geral, estas faltas denotam mais um estacionamento que uma retrogradação, porquanto o Espírito é suscetível de se adiantar ou de parar, nunca, porém, de retroceder.', 'rascunho'),
  (399, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VII — Da volta do Espírito à vida corporal', 'Sendo as vicissitudes da vida corporal expiação das faltas do passado e, ao mesmo tempo, provas com vistas ao futuro, seguir-se-á que da natureza de tais vicissitudes se possa deduzir de que gênero foi a existência anterior?', 'Muito amiúde é isso possível, pois que cada um é punido naquilo por onde pecou. Entretanto, não há que tirar daí uma regra absoluta. As tendências instintivas constituem indício mais seguro, visto que as provas por que passa o Espírito o são, tanto pelo que respeita ao passado, quanto pelo que toca ao futuro." Chegado ao termo que a Providência lhe assinou à vida na erraticidade, o próprio Espírito escolhe as provas a que deseja submeter-se para apressar o seu adiantamento, isto é, escolhe meios de adiantar-se e tais provas estão sempre em relação com as faltas que lhe cumpre expiar. Se delas triunfa, eleva-se; se sucumbe, tem que recomeçar. O Espírito goza sempre do livre-arbítrio. Em virtude dessa liberdade é que escolhe, quando desencarnado, as provas da vida corporal e que, quando encarnado, decide fazer ou não uma coisa e procede à escolha entre o bem e o mal. Negar ao homem o livre--arbítrio fora reduzi-lo à condição de máquina. Mergulhado na vida corpórea, perde o Espírito, momentaneamente, a lembrança de suas existências anteriores, como se um véu as cobrisse. Todavia, conserva algumas vezes vaga consciência dessas vidas, que, mesmo em certas circunstâncias, lhe podem ser reveladas. Esta revelação, porém, só os Espíritos superiores espontaneamente lha fazem, com um fim útil, nunca para satisfazer a vã curiosidade. As existências futuras, essas em nenhum caso podem ser reveladas, pela razão de que dependem do modo por que o Espírito se sairá da existência atual e da escolha que ulteriormente faça. O esquecimento das faltas praticadas não constitui obstáculo à melhoria do Espírito, porquanto, se é certo que este não se lembra delas com precisão, não menos certo é que a circunstância de as ter conhecido na erraticidade e de haver desejado repará-las o guia por intuição e lhe dá a idéia de resistir ao mal, idéia que é a voz da consciência, tendo a secundá-la os Espíritos superiores que o assistem, se atende às boas inspirações que lhe dão. O homem não conhece os atos que praticou em suas existências pretéritas, mas pode sempre saber qual o gênero das faltas de que se tornou culpado e qual o cunho predominante do seu caráter. Bastará então julgar do que foi, não pelo que é, sim, pelas suas tendências. As vicissitudes da vida corpórea constituem expiação das faltas do passado e, simultaneamente, provas com relação ao futuro. Depuram-nos e elevam-nos, se as suportamos resignados e sem murmurar. A natureza dessas vicissitudes e das provas que sofremos também nos podem esclarecer acerca do que fomos e do que fizemos, do mesmo modo que neste mundo julgamos dos atos de um culpado pelo castigo que lhe inflige a lei. Assim, o orgulhoso será castigado no seu orgulho, mediante a humilhação de uma existência subalterna; o mau rico, o avarento, pela miséria; o que foi cruel para os outros, pelas crueldades que sofrerá; o tirano, 152 – Allan Kar dec pela escravidão; o mau filho, pela ingratidão de seus filhos; o preguiçoso, por um trabalho forçado, etc.', 'rascunho'),
  (400, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'O Espírito encarnado permanece de bom grado no seu envoltório corporal?', 'É como se perguntasses se ao encarcerado agrada o cárcere. O Espírito encarnado aspira constantemente à sua libertação e tanto mais deseja ver-se livre do seu invólucro, quanto mais grosseiro é este.', 'rascunho'),
  (401, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Durante o sono, a alma repousa como o corpo?', 'Não, o Espírito jamais está inativo. Durante o sono, afrouxam-se os laços que o prendem ao corpo e, não precisando este então da sua presença, ele se lança pelo espaço e entra em relação mais direta com os outros Espíritos.', 'rascunho'),
  (402, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Como podemos julgar da liberdade do Espírito durante o sono?', 'Pelos sonhos. Quando o corpo repousa, acredita-o, tem o Espírito mais faculdades do que no estado de vigília. Lembra-se do passado e algumas vezes prevê o futuro. Adquire maior potencialidade e pode pôr-se em comunicação com os demais Espíritos, quer deste mundo, quer do outro. Dizes freqüentemente: Tive um sonho extravagante, um sonho horrível, mas absolutamente inverossímil. Enganas- te. É amiúde uma recordação dos lugares e das coisas que viste ou que verás em outra existência ou em outra ocasião. Estando entorpecido o corpo, o Espírito trata de quebrar seus grilhões e de investigar no passado ou no futuro." "Pobres homens, que mal conheceis os mais vulgares fenômenos da vida! Julgais-vos muito sábios e as coisas mais comezinhas vos confundem. Nada sabeis 154 – Allan Kar dec responder a estas perguntas que todas as crianças formulam: Que fazemos quando dormimos? Que são os sonhos?" "O sono liberta a alma parcialmente do corpo. Quando dorme, o homem se acha por algum tempo no estado em que fica permanentemente depois que morre. Tiveram sonos inteligentes os Espíritos que, desencarnando, logo se desligam da matéria. Esses Espíritos, quando dormem, vão para junto dos seres que lhes são superiores. Com estes viajam, conversam e se instruem. Trabalham mesmo em obras que se lhes deparam concluídas, quando volvem, morrendo na Terra, ao mundo espiritual. Ainda esta circunstância é de molde a vos ensinar que não deveis temer a morte, pois que todos os dias morreis, como disse um santo." "Isto, pelo que concerne aos Espíritos elevados. Pelo que respeita ao grande número de homens que, morrendo, têm que passar longas horas na perturbação, na incerteza de que tantos já vos falaram, esses vão, enquanto dormem, ou a mundos inferiores à Terra, onde os chamam velhas afeições, ou em busca de gozos quiçá mais baixos do que os em que aqui tanto se deleitam. Vão beber doutrinas ainda mais vis, mais ignóbeis, mais funestas do que as que professam entre vós. E o que gera a simpatia na Terra é o fato de sentir-se o homem, ao despertar, ligado pelo coração àqueles com quem acaba de passar oito ou nove horas de ventura ou de prazer. Também as antipatias invencíveis se explicam pelo fato de sentirmos em nosso íntimo que os entes com quem antipatizamos têm uma consciência diversa da nossa. Conhecemo-los sem nunca os termos visto com os olhos. É ainda o que explica a indiferença de muitos homens. Não cuidam de conquistar novos amigos, por saberem que muitos têm que os amam e lhes querem. Numa palavra: o sono influi mais do que supondes na vossa vida." "Graças ao sono, os Espíritos encarnados estão sempre em relação com o mundo dos Espíritos. Por isso é que os Espíritos superiores assentem, sem grande repugnância, em encarnar entre vós. Quis Deus que, tendo de estar em contacto com o vício, pudessem eles ir retemperar-se na fonte do bem, a fim de igualmente não falirem, quando se propõem a instruir os outros. O sono é a porta que Deus lhes abriu, para que possam ir ter com seus amigos do céu; é o recreio depois do trabalho, enquanto esperam a grande libertação, a libertação final, que os restituirá ao meio que lhes é próprio." "O sonho é a lembrança do que o Espírito viu durante o sono. Notai, porém, que nem sempre sonhais. Que quer isso dizer? Que nem sempre vos lembrais do que vistes, ou de tudo o que haveis visto, enquanto dormíeis. É que não tendes então a alma no pleno desenvolvimento de suas faculdades. Muitas vezes, apenas vos fica a lembrança da perturbação que o vosso Espírito experimenta à sua partida ou no seu regresso, acrescida da que resulta do que fizestes ou do que vos preocupa quando despertos. A não ser assim, como explicaríeis os sonhos absurdos, que tanto os sábios, quanto as mais humildes e simples criaturas têm? Acontece também que os maus Espíritos se aproveitam dos sonhos para atormentar as almas fracas e pusilânimes." "Em suma, dentro em pouco vereis vulgarizar-se outra espécie de sonhos. Conquanto tão antiga como a de que vimos falando, vós a desconheceis. Refiro-me aos sonhos de Joana, ao de Jacob, aos dos profetas judeus e aos de alguns adivinhos indianos. São recordações guardadas por almas que se desprendem quase inteiramente do corpo, recordações dessa segunda vida a que ainda há pouco aludíamos. Tratai de distinguir essas duas espécies de sonhos nos de que vos lembrais, do contrário cairíeis em contradições e em erros funestos à vossa fé." Os sonhos são efeito da emancipação da alma, que mais independente se torna pela suspensão da vida ativa e de relação. Daí uma espécie de clarividência indefinida que se alonga até aos mais afastados lugares e até mesmo a outros mundos. Daí também a lembrança que traz à memória acontecimentos da precedente existência ou das existências anteriores. As singulares imagens do que se passa ou se passou em mundos desconhecidos, entremeados de coisas do mundo atual, é que formam esses conjuntos estranhos e confusos, que nenhum sentido ou ligação parecem ter. A incoerência dos sonhos ainda se explica pelas lacunas que apresenta a recordação incompleta que conservamos do que nos apareceu quando sonhávamos. É como se a uma narração se truncassem frases ou trechos ao acaso. Reunidos depois, os fragmentos restantes nenhuma significação racional teriam.', 'rascunho'),
  (403, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Por que não nos lembramos sempre dos sonhos?', 'Em o que chamas sono, só há o repouso do corpo, visto que o Espírito está constantemente em atividade. Recobra, durante o sono, um pouco da sua liberdade e se corresponde com os que lhe são caros, quer neste mundo, quer em outros. Mas, como é pesada e grosseira a matéria que o compõe, o corpo dificilmente conserva as impressões que o Espírito recebeu, porque a este não chegaram por intermédio dos órgãos corporais.', 'rascunho'),
  (404, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Que se deve pensar das significações atribuídas aos sonhos?', 'Os sonhos não são verdadeiros como o entendem os ledores de buena- dicha, pois fora absurdo crer-se que sonhar com tal coisa anuncia tal outra. São verdadeiros no sentido de que apresentam imagens que para o Espírito têm realidade, porém que, freqüentemente, nenhuma relação guardam com o que se passa na vida corporal. São também, como atrás dissemos, um pressentimento do futuro, permitido por Deus, ou a visão do que no momento ocorre em outro lugar a que a alma se transporta. Não se contam por muitos os casos de pessoas que em sonho aparecem a seus parentes e amigos, a fim de avisá-los do que a elas está acontecendo? Que são essas aparições senão as almas ou Espíritos de tais pessoas a se comunicarem com entes caros? Quando tendes certeza de que o que vistes realmente se deu, não fica provado que a imaginação nenhuma parte tomou na ocorrência, sobretudo se o que observastes não vos passava pela mente quando em vigília?', 'rascunho'),
  (405, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Acontece com freqüência verem-se em sonho coisas que parecem um pressentimento, que, afinal, não se confirma. A que se deve atribuir isto?', 'Pode suceder que tais pressentimentos venham a confirmar-se apenas para o Espírito. Quer dizer que este viu aquilo que desejava, foi ao seu encontro. É preciso não esquecer que, durante o sono, a alma está mais ou menos sob a influência da matéria e que, por conseguinte, nunca se liberta completamente de suas idéias terrenas, donde resulta que as preocupações do estado de vigília podem dar ao que se vê a aparência do que se deseja, ou do que se teme. A isto é que, em verdade, 156 – Allan Kar dec cabe chamar-se efeito da imaginação. Sempre que uma idéia nos preocupa fortemente, tudo o que vemos se nos mostra ligado a essa idéia.', 'rascunho'),
  (406, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Quando em sonho vemos pessoas vivas, muito nossas conhecidas, a praticarem atos de que absolutamente não cogitam, não é isso puro efeito de imaginação?', 'De que absolutamente não cogitam, dizes. Que sabes a tal respeito? Os Espíritos dessas pessoas vêm visitar o teu, como o teu os vai visitar, sem que saibas sempre o em que eles pensam. Demais, não é raro atribuirdes, de acordo com o que desejais, a pessoas que conheceis, o que se deu ou se está dando em outras existências.', 'rascunho'),
  (407, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'É necessário o sono completo para a emancipação do Espírito?', 'Não; basta que os sentidos entrem em torpor para que o Espírito recobre a sua liberdade. Para se emancipar, ele se aproveita de todos os instantes de trégua que o corpo lhe concede. Desde que haja prostração das forças vitais, o Espírito se desprende, tornando-se tanto mais livre, quanto mais fraco for o corpo." Assim se explica que imagens idênticas às que vemos, em sonho, vejamos estando apenas meio dormindo, ou em simples modorra.', 'rascunho'),
  (408, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'E qual a razão de ouvirmos, algumas vezes em nós mesmos, palavras pronunciadas distintamente e que nenhum nexo têm com o que nos preocupa?', 'É fato: ouvis até mesmo frases inteiras, principalmente quando os sentidos começam a entorpecer-se. É, quase sempre, fraco eco do que diz um Espírito que convosco se quer comunicar.', 'rascunho'),
  (409, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Doutras vezes, num estado que ainda não é bem o do adormecimento, estando com os olhos fechados, vemos imagens distintas, figuras cujas mínimas particularidades percebemos. Que há aí, efeito de visão ou de imaginação?', 'Estando entorpecido o corpo, o Espírito trata de desprender-se. Transporta-se e vê. Se já fosse completo o sono, haveria sonho.', 'rascunho'),
  (410, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Dá-se também que, durante o sono, ou quando nos achamos apenas ligeiramente adormecidos, acodem-nos idéias que nos parecem excelentes e que se nos apagam da memória, apesar dos esforços que façamos para retê-las. Donde vêm essas idéias?', 'Provêm da liberdade do Espírito que se emancipa e que, emancipado, goza de suas faculdades com maior amplitude. Também são, freqüentemente, conselhos que outros Espíritos dão." a) — De que servem essas idéias e esses conselhos, desde que, pelos esquecer, não os podemos aproveitar? "Essas idéias, em regra, mais dizem respeito ao mundo dos Espíritos do que ao mundo corpóreo. Pouco importa que comumente o Espírito as esqueça, quando unido ao corpo. Na ocasião oportuna, voltar-lhe-ão como inspiração de momento.', 'rascunho'),
  (411, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Estando desprendido da matéria e atuando como Espírito, sabe o Espírito encarnado qual será a época de sua morte?', 'Acontece pressenti-la. Também sucede ter plena consciência dessa época, o que dá lugar a que, em estado de vigília, tenha a intuição do fato. Por isso é que algumas pessoas prevêem com grande exatidão a data em que virão a morrer.', 'rascunho'),
  (412, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Pode a atividade do Espírito, durante o repouso, ou o sono corporal, fatigar o corpo?', 'Pode, pois que o Espírito se acha preso ao corpo qual balão cativo ao poste. Assim como as sacudiduras do balão abalam o poste, a atividade do Espírito reage sobre o corpo e pode fatigá-lo.', 'rascunho'),
  (413, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Do princípio da emancipação da alma parece decorrer que temos duas existências simultâneas: a do corpo, que nos permite a vida de relação ostensiva; e a da alma, que nos proporciona a vida de relação oculta. É assim?', 'No estado de emancipação, prima a vida da alma. Contudo, não há, verdadeiramente, duas existências. São antes duas fases de uma só existência, porquanto o homem não vive duplamente.', 'rascunho'),
  (414, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Podem duas pessoas que se conhecem visitar-se durante o sono?', 'Certo e muitos que julgam não se conhecerem costumam reunir-se e falar- se. Podes ter, sem que o suspeites, amigos em outro país. É tão habitual o fato de irdes encontrar-vos, durante o sono, com amigos e parentes, com os que conheceis e que vos podem ser úteis, que quase todas as noites fazeis essas visitas.', 'rascunho'),
  (415, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Que utilidade podem elas ter, se as olvidamos?', 'De ordinário, ao despertardes, guardais a intuição desse fato, do qual se originam certas idéias que vos vêm espontaneamente, sem que possais explicar como vos acudiram. São idéias que adquiristes nessas confabulações.', 'rascunho'),
  (416, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Pode o homem, pela sua vontade, provocar as visitas espíritas? Pode, por exemplo, dizer, quando está para dormir: Quero esta noite encontrar-me em Espírito com Fulano, quero falar-lhe para dizer isto?', 'O que se dá é o seguinte: Adormecendo o homem, seu Espírito desperta e, muitas vezes, nada disposto se mostra a fazer o que o homem resolvera, porque a vida deste pouco interessa ao seu Espírito, uma vez desprendido da matéria. Isto com relação a homens já bastante elevados espiritualmente. Os outros passam de modo muito diverso a fase espiritual de sua existência terrena. Entregam-se às paixões que os escravizaram, ou se mantêm inativos. Pode, pois, suceder, tais sejam os motivos que a isso o induzem, que o Espírito vá visitar aqueles com quem deseja encontrar-se. Mas, não constitui razão, para que semelhante coisa se verifique, o simples fato de ele o querer quando desperto." 158 – Allan Kar dec', 'rascunho'),
  (417, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Podem Espíritos encarnados reunir-se em certo número e formar assembléias?', 'Sem dúvida alguma. Os laços, antigos ou recentes, da amizade costumam reunir desse modo diversos Espíritos, que se sentem felizes de estar juntos." Pelo termo antigos se devem entender os laços de amizade contraída em existências anteriores. Ao despertar, guardamos intuição das idéias que haurimos nesses colóquios, mas ficamos na ignorância da fonte donde promanaram.', 'rascunho'),
  (418, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Uma pessoa que julgasse morto um de seus amigos, sem que tal fosse a realidade, poderia encontrar-se com ele, em Espírito, e verificar que continuava vivo? E, dado o fato, poderia, ao despertar, ter dele a intuição?', 'Como Espírito, a pessoa que figuras pode ver o seu amigo e conhecer-lhe a sorte. Se lhe não houver sido imposto, por prova, crer na morte desse amigo, poderá ter um pressentimento da sua existência, como poderá tê-lo de sua morte.', 'rascunho'),
  (419, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Que é o que dá causa a que uma idéia, a de uma descoberta, por exemplo, surja em muitos pontos ao mesmo tempo?', 'Já dissemos que durante o sono os Espíritos se comunicam entre si. Ora bem! Quando se dá o despertar, o Espírito se lembra do que aprendeu e o homem julga ser isso um invento de sua autoria. Assim é que muitos podem simultaneamente descobrir a mesma coisa. Quando dizeis que uma idéia paira no ar, usais de uma figura de linguagem mais exata do que supondes. Todos, sem o suspeitarem, contribuem para propagá-la." Desse modo, o nosso próprio Espírito revela muitas vezes, a outros Espíritos, mau grado nosso, o que constituía objeto de nossas preocupações no estado de vigília.', 'rascunho'),
  (420, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Podem os Espíritos comunicar-se, estando completamente despertos os corpos?', 'O Espírito não se acha encerrado no corpo como numa caixa; irradia por todos os lados. Segue-se que pode comunicar-se com outros Espíritos, mesmo em estado de vigília, se bem que mais dificilmente.', 'rascunho')
